window.ACDT_CHATEAUX_TXT = window.ACDT_CHATEAUX_TXT || {}; window.ACDT_CHATEAUX_TXT["ru"] = {"ch-Q2946":{"n":"Версаль","c":"французский дворцово-парковый ансамбль в пригороде Парижа","r":"Верса́ль — дворцово-парковый ансамбль во Франции, бывшая резиденция французских королей в городе Версаль, ныне являющемся пригородом Парижа; центр туризма мирового значения.","w":"https://ru.wikipedia.org/wiki/%D0%92%D0%B5%D1%80%D1%81%D0%B0%D0%BB%D1%8C"},"ch-Q1143049":{"n":"замок Монсоро","c":"замок во Франции","r":"Замок Монсоро — замок во Франции, возведённый в готическом и ренессансном стиле. Расположен в долине Луары, в коммуне Монсоро на юго-востоке департамента Мен и Луара, в регионе Пеи-де-ла-Луар. 8 апреля 2016 года открыт Музей современного искусства «Замок Монсоро».","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%9C%D0%BE%D0%BD%D1%81%D0%BE%D1%80%D0%BE"},"ch-Q201428":{"n":"Дворец Фонтенбло","c":"французский королевский дворец в 70 км от Парижа","r":"Дворец (замок) Фонтенбло́ — королевский дворец во Франции, расположенный в департаменте Сена и Марна, в 70 км к юго-востоку от Парижа. Вокруг дворца со временем сформировался город Фонтенбло.","w":"https://ru.wikipedia.org/wiki/%D0%94%D0%B2%D0%BE%D1%80%D0%B5%D1%86_%D0%A4%D0%BE%D0%BD%D1%82%D0%B5%D0%BD%D0%B1%D0%BB%D0%BE"},"ch-Q205367":{"n":"Замок Шамбор","r":"За́мок Шамбо́р или Шамбо́рский замок — один из замков Луары. Построен по распоряжению короля Франциска I, который хотел быть ближе к любимой даме — графине Тури[уточнить], жившей неподалёку. Строительство велось между 1519 и 1547 годами на изгибе реки Коссон — небольшого притока реки Бёврон, впадающей в Луару, приблизительно в 6 км от левого берега Луары и в 14 км на восток от Блуа во французском департаменте Луар и Шер. В 2000 году вместе с другими замками долины Луары внесён в список Всемирного наследия ЮНЕСКО под номером 933.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%A8%D0%B0%D0%BC%D0%B1%D0%BE%D1%80"},"ch-Q329852":{"n":"Люксембургский дворец","c":"дворец в Париже","r":"Люксембургский дворец — дворцово-парковый ансамбль в Париже, памятник архитектуры раннего классицизма, построенный для Марии Медичи по проекту Саломона Деброса в 1615—1631 годах в Люксембургском саду в, близ Латинского квартала, на месте Люксембургского отеля (особняка) покойного герцога Франсуа де Пине из рода Люксембургов.","w":"https://ru.wikipedia.org/wiki/%D0%9B%D1%8E%D0%BA%D1%81%D0%B5%D0%BC%D0%B1%D1%83%D1%80%D0%B3%D1%81%D0%BA%D0%B8%D0%B9_%D0%B4%D0%B2%D0%BE%D1%80%D0%B5%D1%86"},"ch-Q143463":{"n":"Папский дворец","c":"дворец и музей в Авиньоне, Франция","r":"Папский дворец — памятник истории и архитектуры в Авиньоне, Франция. Объект Всемирного наследия ЮНЕСКО и один из крупнейших дворцов в Европе. Место проведения ежегодного театрального фестиваля.","w":"https://ru.wikipedia.org/wiki/%D0%9F%D0%B0%D0%BF%D1%81%D0%BA%D0%B8%D0%B9_%D0%B4%D0%B2%D0%BE%D1%80%D0%B5%D1%86_(%D0%90%D0%B2%D0%B8%D0%BD%D1%8C%D0%BE%D0%BD)"},"ch-Q193215":{"n":"Замок Шенонсо","r":"Замок Шенонсо расположен около небольшой одноимённой деревни Шенонсо во французском департаменте Эндр и Луара. Входит в число замков, обычно называемых замками Луары. Имеет «народное» название — «дамский замок». Один из наиболее любимых, известных и посещаемых замков Франции. Является частной собственностью, но открыт для посещения.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%A8%D0%B5%D0%BD%D0%BE%D0%BD%D1%81%D0%BE"},"ch-Q936633":{"n":"Бурбонский дворец","c":"место заседаний Национальной ассамблеи Франции в Париже","r":"Бурбонский дворец — место заседаний Национальной ассамблеи Франции в Париже, на левом берегу Сены, на набережной Орсе, прямо напротив церкви Мадлен и площади Согласия, с которой он соединён мостом Согласия.","w":"https://ru.wikipedia.org/wiki/%D0%91%D1%83%D1%80%D0%B1%D0%BE%D0%BD%D1%81%D0%BA%D0%B8%D0%B9_%D0%B4%D0%B2%D0%BE%D1%80%D0%B5%D1%86"},"ch-Q4055":{"n":"Замок Блуа","c":"самый крупный по размерам из замков Луары","r":"За́мок Блуа́ — самый крупный по размерам из замков Луары, резиденция французских королей Людовика XII и Франциска I.","w":"https://ru.wikipedia.org/wiki/%D0%91%D0%BB%D1%83%D0%B0_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q739976":{"n":"Во-ле-Виконт","c":"классическая французская усадьба—дворец 17 века","r":"Во-ле-Вико́нт — классическая французская усадьба-дворец XVII века, расположенная в Менси, в окрестностях Мелёна, в 50 км к юго-востоку от Парижа. Построена в 1658—1661 годах для Николя Фуке, виконта Во и Мелёна, суперинтенданта финансов при короле Людовике XIV. Выдающийся памятник архитектуры «Большого стиля» эпохи Короля-Солнца, соединяющий элементы французского классицизма и итальянского барокко.","w":"https://ru.wikipedia.org/wiki/%D0%92%D0%BE-%D0%BB%D0%B5-%D0%92%D0%B8%D0%BA%D0%BE%D0%BD%D1%82"},"ch-Q663673":{"n":"Венсенский замок","c":"замок XIV века в коммуне Венсен, пригород Парижа, Франция","r":"Венсе́нский за́мок — замок французских королей XIII—XVII столетий в Венсенском лесу, построенный на месте охотничьего поместья XII века. Вокруг замка сложился город Венсен, в наши дни — юго-восточное предместье Парижа.","w":"https://ru.wikipedia.org/wiki/%D0%92%D0%B5%D0%BD%D1%81%D0%B5%D0%BD%D1%81%D0%BA%D0%B8%D0%B9_%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA"},"ch-Q1075988":{"n":"Луврский дворец","c":"старинный перестроенный во дворец королевский замок в Париже","r":"Лу́врский дворе́ц, в других переводах дворе́ц Лу́вра, или просто Лувр — старинный королевский замок в Париже, перестроенный во дворец, расположенный на правом берегу Сены между садом Тюильри и церковью Сен-Жермен-л’Осеруа; главная выставочная часть одноимённого музея — одного из богатейших в мире художественных собраний.","w":"https://ru.wikipedia.org/wiki/%D0%9B%D1%83%D0%B2%D1%80%D1%81%D0%BA%D0%B8%D0%B9_%D0%B4%D0%B2%D0%BE%D1%80%D0%B5%D1%86"},"ch-Q389908":{"n":"Амбуаз","r":"Амбуа́зский за́мок — историко-архитектурный комплекс во Франции. Возвышается над Луарой в городе Амбуаз, департамент Эндр и Луара. Это один из замков Луары, который с 2000 года относится ко Всемирному наследию ЮНЕСКО, как часть «долины Луары от Сюлли-сюр-Луар до Шалонна».","w":"https://ru.wikipedia.org/wiki/%D0%90%D0%BC%D0%B1%D1%83%D0%B0%D0%B7_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1520841":{"n":"Сен-Жерменский дворец","r":"Сен-Жерменский дворец — бывшая королевская резиденция в парижском предместье Сен-Жермен-ан-Ле, в виду берегов Сены, ныне музей национальной археологии Франции.","w":"https://ru.wikipedia.org/wiki/%D0%A1%D0%B5%D0%BD-%D0%96%D0%B5%D1%80%D0%BC%D0%B5%D0%BD%D1%81%D0%BA%D0%B8%D0%B9_%D0%B4%D0%B2%D0%BE%D1%80%D0%B5%D1%86"},"ch-Q912192":{"n":"Матиньонский дворец","c":"резиденция премьер-министра Франции","r":"Матиньонский дворец, реже отель Матиньон — официальная резиденция премьер-министра французского правительства, расположенная по адресу ул. Варенн 57 (Varenne) в 7-м округе Парижа.","w":"https://ru.wikipedia.org/wiki/%D0%9C%D0%B0%D1%82%D0%B8%D0%BD%D1%8C%D0%BE%D0%BD%D1%81%D0%BA%D0%B8%D0%B9_%D0%B4%D0%B2%D0%BE%D1%80%D0%B5%D1%86"},"ch-Q13360213":{"n":"Дворец Шайо","c":"здание в Париже на правом берегу Сены, напротив Марсова поля и Эйфелевой башни","r":"Дворец Шайо — здание в Париже на правом берегу Сены, напротив Марсова поля и Эйфелевой башни. Построено по проекту Л. Буало, Ж. Карлю и Л. Азема к Всемирной выставке 1937 года на месте стоявшего ранее «Дворца Трокадеро».","w":"https://ru.wikipedia.org/wiki/%D0%94%D0%B2%D0%BE%D1%80%D0%B5%D1%86_%D0%A8%D0%B0%D0%B9%D0%BE"},"ch-Q113389":{"n":"Замок Азе-лё-Ридо","c":"замок во Франции","r":"Азе́-лё-Ридо́ — замок во Франции, государственный исторический памятник в одноимённой коммуне французского департамента Эндр и Луара, в 20 км на запад от Тура в направлении Шинона. Принадлежит к избранному числу замков Луары. Окружен английским парком.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%90%D0%B7%D0%B5-%D0%BB%D1%91-%D0%A0%D0%B8%D0%B4%D0%BE"},"ch-Q578771":{"n":"Дворец То","c":"дворец в Реймсе","r":"Дворец То — дворец во французском городе Реймс, историческая резиденция архиепископов Реймсских. История дворца неразрывно связана с французской монархией, так как коронация королей проходила в примыкающем к нему Реймсском соборе.","w":"https://ru.wikipedia.org/wiki/%D0%94%D0%B2%D0%BE%D1%80%D0%B5%D1%86_%D0%A2%D0%BE"},"ch-Q477613":{"n":"Замок Вилландри","r":"За́мок Вилландри́ входит в избранное число замков Луары во Франции, расположен в 15 км на запад от города Тура по шоссе D7. Известен своими 3 садами, донжоном, высящимся над декоративными огородами, садом в орнаментах и садом с прудом.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%92%D0%B8%D0%BB%D0%BB%D0%B0%D0%BD%D0%B4%D1%80%D0%B8"},"ch-Q766938":{"n":"Замок Шантийи","c":"замок в Шантийи, Франция","r":"Шантийи — одна из наиболее значительных аристократических резиденций Франции эпохи старого порядка. Находится недалеко от Парижа в коммуне Шантийи, в долине реки Нонетт, притока реки Уазы.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%A8%D0%B0%D0%BD%D1%82%D0%B8%D0%B9%D0%B8"},"ch-Q1122731":{"n":"Кло-Люсе","r":"Клу или Кло-Люсе — французский средневековый замок, один из самых известных замков Луары. Дом-музей Леонардо да Винчи.","w":"https://ru.wikipedia.org/wiki/%D0%9A%D0%BB%D0%BE-%D0%9B%D1%8E%D1%81%D0%B5"},"ch-Q912447":{"n":"Шинон","r":"Замок Шинон — замок в городе Шинон, находится у реки Вьенна, один из королевских замков Луары. Построен на месте бывших римских укреплений и состоит из трёх частей, строившихся по мере исторической надобности. Любимая резиденция английского короля Генриха II.","w":"https://ru.wikipedia.org/wiki/%D0%A8%D0%B8%D0%BD%D0%BE%D0%BD_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1048155":{"n":"Анжерский замок","r":"Анже́рский за́мок расположен в городе Анже в департаменте Мен и Луара во Франции. Общая площадь замка составляет около 25 000 м².","w":"https://ru.wikipedia.org/wiki/%D0%90%D0%BD%D0%B6%D0%B5%D1%80%D1%81%D0%BA%D0%B8%D0%B9_%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA"},"ch-Q684846":{"n":"Мальмезон","c":"замок и музей в Рюэй-Мальмезоне, Франция","r":"Мальмезон — усадьба в 20 км от Парижа, наиболее известная как частная резиденция Наполеона Бонапарта и Жозефины Богарне.","w":"https://ru.wikipedia.org/wiki/%D0%9C%D0%B0%D0%BB%D1%8C%D0%BC%D0%B5%D0%B7%D0%BE%D0%BD"},"ch-Q1150222":{"n":"Сомюр","c":"замок во Франции на реке Луаре","r":"Замок Сомюр — один из замков Луары, расположен в городе Сомюр на слиянии рек Луары и Туэ (Thouet) в департаменте Мен и Луара Франции. В 1862 году внесён Министерством культуры Франции в список исторических памятников Франции.","w":"https://ru.wikipedia.org/wiki/%D0%A1%D0%BE%D0%BC%D1%8E%D1%80_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q376699":{"n":"Пьерфон","c":"французский замок","r":"Замок Пьерфон — замок на юго-восточной окраине Компьенского леса, расположен между городами Компьень и Вилле-Котре.","w":"https://ru.wikipedia.org/wiki/%D0%9F%D1%8C%D0%B5%D1%80%D1%84%D0%BE%D0%BD_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1552366":{"n":"Верхний Кёнигсбург","c":"Замок в Эльзасе, Франция","r":"Верхний Кёнигсбург — средневековый замок, воссозданный из руин (реконструированный) 100 лет назад для кайзера Вильгельма II. Расположен в Эльзасе (Франция), в 10 км от города Селеста.","w":"https://ru.wikipedia.org/wiki/%D0%92%D0%B5%D1%80%D1%85%D0%BD%D0%B8%D0%B9_%D0%9A%D1%91%D0%BD%D0%B8%D0%B3%D1%81%D0%B1%D1%83%D1%80%D0%B3"},"ch-Q185479":{"n":"Замок Юссе","r":"Замок Юссе — средневековый замок на реке Эндр, расположенный в долине Луары, во французском департаменте Эндр и Луара.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%AE%D1%81%D1%81%D0%B5"},"ch-Q1143558":{"n":"Ланже","c":"Замок во Франции","r":"Замок Ланже́ [ланжэ] во французском департаменте Эндр и Луара был заложен в конце X века анжуйским графом Фульком Нерра на нависшей над долиной Луары скале. В XII веке замок был расширен его потомком Ричардом Львиное Сердце.","w":"https://ru.wikipedia.org/wiki/%D0%9B%D0%B0%D0%BD%D0%B6%D0%B5_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q522779":{"n":"Шомон-сюр-Луар","r":"Замок Шомон-сюр-Луар — средневековый замок, находится во Франции на берегу Луары, между городами Амбуаз и Блуа. Принадлежит к избранному числу замков Луары. Здесь проводится Международный садовый фестиваль.","w":"https://ru.wikipedia.org/wiki/%D0%A8%D0%BE%D0%BC%D0%BE%D0%BD-%D1%81%D1%8E%D1%80-%D0%9B%D1%83%D0%B0%D1%80_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1141846":{"n":"Шеверни","r":"Замок Шеверни — один из замков Луары в одноимённой коммуне области Солонь во Франции.","w":"https://ru.wikipedia.org/wiki/%D0%A8%D0%B5%D0%B2%D0%B5%D1%80%D0%BD%D0%B8_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1011806":{"n":"Фуа (замок)","r":"За́мок Фуа́ — французский замок знаменитых в Средние века графов Фуа, возвышающийся над городом Фуа в Пиренеях. Важный туристический объект.","w":"https://ru.wikipedia.org/wiki/%D0%A4%D1%83%D0%B0_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1013191":{"n":"Монсегюр","r":"Монсегюр — небольшое оборонительное сооружение, находящееся на вершине пог — или печ — в отрогах Пиренеев, неподалёку от пика св. Варфоломея. Современная крепость описывается в мифах как катарская цитадель, хотя это остатки крепости более позднего периода, и остатки укреплений, о которых сложено множество легенд и преданий, вообще не имеют отношения к эпохе катаров.","w":"https://ru.wikipedia.org/wiki/%D0%9C%D0%BE%D0%BD%D1%81%D0%B5%D0%B3%D1%8E%D1%80"},"ch-Q1470842":{"n":"Сюлли-сюр-Луар","r":"Сюлли-сюр-Луар — средневековый луарский замок (шато), резиденция герцогов де Сюлли, до 1962 года принадлежавший знатному семейству Бетюнов, наиболее известным представителем которого был Максимильен де Бетюн Сюлли, 1-й герцог де Сюлли (1560–1641), соратник и министр финансов короля Генриха IV. Во время Фронды в нём прятались Анна Австрийская и кардинал Мазарини. В начале XVIII века Вольтер, преследуемый из-за своих сатирических произведений, нашёл здесь убежище от гнева регента Филиппа Орлеанского.","w":"https://ru.wikipedia.org/wiki/%D0%A1%D1%8E%D0%BB%D0%BB%D0%B8-%D1%81%D1%8E%D1%80-%D0%9B%D1%83%D0%B0%D1%80_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q786075":{"n":"Бриссак","r":"Бриссак — замок в долине Луары, в районе Бриссак-Квинсе коммуны Бриссак-Луар-Оберж, расположенный в департаменте Мэн и Луара, Франция. Собственность принадлежит семье Коссе, глава которой носит французский наследственный титул герцога Бриссака. Министерство культуры Франции внесло замок в список исторических памятников.","w":"https://ru.wikipedia.org/wiki/%D0%91%D1%80%D0%B8%D1%81%D1%81%D0%B0%D0%BA_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1557685":{"n":"Геделон","c":"Французский проект, воссоздающий замок 13-го века","r":"Геделон — современный проект постройки средневекового замка во Франции, близ города Треньи.","w":"https://ru.wikipedia.org/wiki/%D0%93%D0%B5%D0%B4%D0%B5%D0%BB%D0%BE%D0%BD"},"ch-Q1289258":{"n":"Замок герцогов Бретонских","r":"Замок герцогов Бретонских — замок (шато) в Нанте, считающийся историческим центром герцогства Бретань. Стоит на правом берегу Луары; ранее вода во рву вокруг замка сообщалась с рекой.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%B3%D0%B5%D1%80%D1%86%D0%BE%D0%B3%D0%BE%D0%B2_%D0%91%D1%80%D0%B5%D1%82%D0%BE%D0%BD%D1%81%D0%BA%D0%B8%D1%85"},"ch-Q648534":{"n":"Рамбуйе","c":"Замок во Франции","r":"Рамбуйе́ — замок в городе Рамбуйе, расположен в департаменте Ивелин, в регионе Иль-де-Франс на севере Франции, в 50 км к юго-западу от Парижа. С 1896 по 2009 год замок использовался как летняя резиденция французских президентов. С 2010 года замком управляет Национальный центр памятников. С 2024 года Шато Рамбуйе является национальным достоянием, замок и всё его содержимое отнесено к категории исторических памятников.","w":"https://ru.wikipedia.org/wiki/%D0%A0%D0%B0%D0%BC%D0%B1%D1%83%D0%B9%D0%B5_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1061469":{"n":"Шато Мутон-Ротшильд","c":"винодельческое хозяйство","r":"Шато Мутон-Ротшильд — бордоское винодельческое хозяйство (шато), расположенное в коммуне Пойяк аппелласьона Верхний Медок. Согласно изменениям, внесённым в 1973 году в «Официальную классификацию вин Бордо», относится к высшей категории винодельческих хозяйств.","w":"https://ru.wikipedia.org/wiki/%D0%A8%D0%B0%D1%82%D0%BE_%D0%9C%D1%83%D1%82%D0%BE%D0%BD-%D0%A0%D0%BE%D1%82%D1%88%D0%B8%D0%BB%D1%8C%D0%B4"},"ch-Q1067494":{"n":"Тампль","r":"Тампль — средневековая крепость в Париже, располагавшаяся на территории современных округов II и III.","w":"https://ru.wikipedia.org/wiki/%D0%A2%D0%B0%D0%BC%D0%BF%D0%BB%D1%8C"},"ch-Q1011026":{"n":"Замок Бейнак","r":"Замок Бенак или Бейнак — внушительное средневековое укрепление во Франции, расположено в долине Дордони, возвышается на высоте ста метров над окрестными землями, на скалистом отроге. У подножия замка — селение Бенак-э-Казнак.","w":"https://ru.wikipedia.org/wiki/%D0%91%D0%B5%D0%BD%D0%B0%D0%BA_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1480604":{"n":"По","c":"за́мок в одноимённом городе во Франции, исторический памятник","r":"Замок По — замок в городе По, некогда столице Беарна. Стоит на холме, возвышающемся над рекой Гав-де-По. Известен с XII века. Окружен палисадом из кольев, символизирующих верность и искренность. От них происходит и название замка.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%9F%D0%BE"},"ch-Q516697":{"n":"Компьенский дворец","c":"замок в Компьене, Франция","r":"Компьенская резиденция — дворец французских королей в городе Компьень департамента Уаза, Пикардия (Франция). Расположен в 75 километрах к северо-северо-востоку от Парижа. В Средние века являлся излюбленной резиденцией Меровингов и Каролингов, современный вид в стиле классицизма принял после реконструкции в XVIII веке. Последним французским монархом, жившим во дворце, был император Наполеон III.","w":"https://ru.wikipedia.org/wiki/%D0%9A%D0%BE%D0%BC%D0%BF%D1%8C%D0%B5%D0%BD%D1%81%D0%BA%D0%B8%D0%B9_%D0%B4%D0%B2%D0%BE%D1%80%D0%B5%D1%86"},"ch-Q1090583":{"n":"Шато Латур","r":"Шато Латур — французское винодельческое хозяйство (шато) района Верхний Медок, который входит в регион Бордо. Расположено вдоль левого берега Жиронды на самом юго-востоке коммуны Пойяк — там, где она граничит с Сен-Жюльеном.","w":"https://ru.wikipedia.org/wiki/%D0%A8%D0%B0%D1%82%D0%BE_%D0%9B%D0%B0%D1%82%D1%83%D1%80"},"ch-Q1063236":{"n":"Шато Марго","r":"Шато́ Марго́ — французское винодельческое хозяйство, расположенное в коммуне Марго округа Медок. Согласно «Официальной классификации вин Бордо 1855 года», относится к категории Premier Grand Cru Classé, то есть высшей категории в классификации. Входит в пятёрку лучших производителей бордо вместе с Château Mouton-Rothschild, Château Lafite-Rothschild, Château Latour и Château Haut-Brion.","w":"https://ru.wikipedia.org/wiki/%D0%A8%D0%B0%D1%82%D0%BE_%D0%9C%D0%B0%D1%80%D0%B3%D0%BE"},"ch-Q1479356":{"n":"Тальси","r":"Тальси́ — средневековый замок во Франции, в долине Луары на левом берегу реки, в центре маленького посёлка Бос.","w":"https://ru.wikipedia.org/wiki/%D0%A2%D0%B0%D0%BB%D1%8C%D1%81%D0%B8_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1815544":{"n":"Шатодён","r":"Замок Шатодён — резиденция графов Дюнуа в городе Шатодён, департамент Эр и Луара. Построен в XII—XVI веках, относится к избранному числу замков Луары. Находится недалеко от Шартра, это первый из списка замков Луары по пути из Парижа.","w":"https://ru.wikipedia.org/wiki/%D0%A8%D0%B0%D1%82%D0%BE%D0%B4%D1%91%D0%BD_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2111621":{"n":"Дворец герцогов Бургундских","r":"Дворец герцогов Бургундских — бывшая резиденция бургундских герцогов в столице Бургундии — городе Дижоне.","w":"https://ru.wikipedia.org/wiki/%D0%94%D0%B2%D0%BE%D1%80%D0%B5%D1%86_%D0%B3%D0%B5%D1%80%D1%86%D0%BE%D0%B3%D0%BE%D0%B2_%D0%91%D1%83%D1%80%D0%B3%D1%83%D0%BD%D0%B4%D1%81%D0%BA%D0%B8%D1%85"},"ch-Q2971342":{"n":"Ла-Мюэтт","r":"Ла-Мюэтт — королевская усадьба, некогда находившаяся на краю Булонского леса возле одноимённых ворот Парижа.","w":"https://ru.wikipedia.org/wiki/%D0%9B%D0%B0-%D0%9C%D1%8E%D1%8D%D1%82%D1%82"},"ch-Q2092716":{"n":"Мезон-Лаффит","r":"Мезо́н-Лаффи́т — знаменитый замок (дворец) во Франции XVII века, одно из немногих сохранившихся творений архитектора Франсуа Мансара. Расположен в одноимённом пригороде Парижа.","w":"https://ru.wikipedia.org/wiki/%D0%9C%D0%B5%D0%B7%D0%BE%D0%BD-%D0%9B%D0%B0%D1%84%D1%84%D0%B8%D1%82"},"ch-Q1090764":{"n":"Шато д’Икем","r":"Шато д’Икем — французское бордоское винодельческое хозяйство, расположенное в коммуне Сотерн. Согласно Официальной классификации вин Бордо 1855 хозяйство относится к категории Premier Cru Supérieur, то есть высшей категории в классификации вин Бордо. Хозяйство входит в список лучших производителей Бордо вместе с левобережной «пятёркой» Premier Grand Cru Classé — хозяйством Château Pétrus из коммуны Помроль, и двумя хозяйствами из коммуны Сент-Эмильон — Château Cheval Blanc и Château Ausone.","w":"https://ru.wikipedia.org/wiki/%D0%A8%D0%B0%D1%82%D0%BE_%D0%B4%E2%80%99%D0%98%D0%BA%D0%B5%D0%BC"},"ch-Q1377160":{"n":"Замок Плесси-Бурре","r":"Замок Плесси-Бурре расположен в коммуне Écuillé неподалёку от Анжера в департаменте Мен и Луара во Франции и является одним из великолепных замков Луары, наравне с такими как Шомон, Шенонсо или Сомюр. Замок прекрасно сохранился и его нынешний вид почти не отличается от того, что был создан почти пять веков назад. Является частной собственностью, но открыт для посещения.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%9F%D0%BB%D0%B5%D1%81%D1%81%D0%B8-%D0%91%D1%83%D1%80%D1%80%D0%B5"},"ch-Q1516747":{"n":"Замок Коммарк","r":"Замок Коммарк — замок во Франции в департаменте Дордонь на территории коммуны Ле-Эзи-де-Тайак-Сирёй, построенный на скалистом утёсе в глубине долины реки Бён. На месте древнего каструма, внутри крепостного пояса укреплений, расположен замок, часовня и жилища представителей родственной знати.","w":"https://ru.wikipedia.org/wiki/%D0%9A%D0%BE%D0%BC%D0%BC%D0%B0%D1%80%D0%BA_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1817122":{"n":"Экуанский замок","r":"Экуа́нский за́мок или замок Экуа́н — французская усадьба (шато) XVI века к северу от Парижа, в департаменте Валь-д’Уаз, историко-архитектурный памятник французского Возрождения. С 1977 года в нём располагается «Национальный музей Ренессанса». Строение принадлежит канцелярии ордена Почетного легиона и находится в ведении министерства культуры.","w":"https://ru.wikipedia.org/wiki/%D0%AD%D0%BA%D1%83%D0%B0%D0%BD%D1%81%D0%BA%D0%B8%D0%B9_%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA"},"ch-Q2060046":{"n":"Замок Роктайад","r":"Замок Роктайа́д — средневековый укреплённый замок, находящийся на юго-западе Франции, в коммуне Мазер департамента Жиронда, регион Новая Аквитания. Один из так называемых «климентовских замков» в Гиени.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%A0%D0%BE%D0%BA%D1%82%D0%B0%D0%B9%D0%B0%D0%B4"},"ch-Q2968752":{"n":"Канский замок","r":"Канский замок — средневековая крепость в центре французского города Кан. Основан Вильгельмом Завоевателем около 1060 года. В 1886 году включён в список исторических памятников.","w":"https://ru.wikipedia.org/wiki/%D0%9A%D0%B0%D0%BD%D1%81%D0%BA%D0%B8%D0%B9_%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA"},"ch-Q2093924":{"n":"замок Аббади","r":"Замок Аббади — неоготическая усадьба (шато) близ города Андай во французском департаменте Атлантические Пиренеи.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%90%D0%B1%D0%B1%D0%B0%D0%B4%D0%B8"},"ch-Q1376597":{"n":"Труссэ","c":"замок во Франции","r":"Труссэ — средневековый замок.","w":"https://ru.wikipedia.org/wiki/%D0%A2%D1%80%D1%83%D1%81%D1%81%D1%8D_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q205659":{"n":"Люневильский дворец","r":"Люневильский дворец — дворец и парковый комплекс во французском городе Люневиль, в департаменте Мёрт и Мозель (Лотарингия).","w":"https://ru.wikipedia.org/wiki/%D0%9B%D1%8E%D0%BD%D0%B5%D0%B2%D0%B8%D0%BB%D1%8C%D1%81%D0%BA%D0%B8%D0%B9_%D0%B4%D0%B2%D0%BE%D1%80%D0%B5%D1%86"},"ch-Q769303":{"n":"Замок Риво","r":"Замок Риво находится на расстоянии 10 минут езды от замка Шинон, на территории коммуны Лемере.","w":"https://ru.wikipedia.org/wiki/%D0%A0%D0%B8%D0%B2%D0%BE_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q761920":{"n":"Жьен","r":"Жьенский замок — шато в городе Жьен, которое оспаривает у Амбуазского замка право считаться первым ренессансным замком Луары. Он был воздвигнут в начале XVI века для проживания королевской дочери Анны де Боже и оставался собственностью графов де Жьен до Французской революции. В 1823 году перешёл к властям департамента Луаре. Перпендикулярно к основному зданию пристроен второй корпус. С 1952 года в замке размещается Международный музей охоты.","w":"https://ru.wikipedia.org/wiki/%D0%96%D1%8C%D0%B5%D0%BD_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1011692":{"n":"Шато-де-Фалез","r":"Замок Фалез — одна из первых каменных крепостей Нижней Нормандии, расположенная на юго-западе города Фалез. Место рождения Вильгельма Завоевателя. Замок приобрёл текущий вид в результате масштабной реконструкции, продолжавшейся с 1987 по 1997 годы.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%A4%D0%B0%D0%BB%D0%B5%D0%B7"},"ch-Q1192381":{"n":"замок Менар","c":"замок в Менаре, Луар и Шер, Франция","r":"Менар — луарское шато маркизы де Помпадур, приобретённое ею в 1760 году за астрономическую сумму в миллион ливров у наследников богатого откупщика Гийома Шаррона, построившего его в 1646 году. Помпадур наняла для расширения дворца королевского архитектора Анжа-Жака Габриэля. После смерти фаворитки усадьбу унаследовал её брат, по заданию которого дворец осовременил Жак-Жермен Суффло.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%9C%D0%B5%D0%BD%D0%B0%D1%80"},"ch-Q1229917":{"n":"Дворец Почётного легиона","r":"Дворец Почётного легиона, или Дворец ордена Почётного легиона — парижский дворцовый комплекс в стиле зрелого классицизма, расположенный на левом берегу Сены напротив садов Тюильри, рядом с музеем Орсе. Во дворце находятся штаб-квартира ордена Почётного легиона и музей военных орденов Франции.","w":"https://ru.wikipedia.org/wiki/%D0%94%D0%B2%D0%BE%D1%80%D0%B5%D1%86_%D0%9F%D0%BE%D1%87%D1%91%D1%82%D0%BD%D0%BE%D0%B3%D0%BE_%D0%BB%D0%B5%D0%B3%D0%B8%D0%BE%D0%BD%D0%B0"},"ch-Q2633625":{"n":"Брестский замок","r":"Брестский замок — сооружение в городе Брест на берегах Пенфельда и Брестского рейда.","w":"https://ru.wikipedia.org/wiki/%D0%91%D1%80%D0%B5%D1%81%D1%82%D1%81%D0%BA%D0%B0%D1%8F_%D0%BA%D1%80%D0%B5%D0%BF%D0%BE%D1%81%D1%82%D1%8C_(%D0%A4%D1%80%D0%B0%D0%BD%D1%86%D0%B8%D1%8F)"},"ch-Q2032524":{"n":"Ане","r":"Дворец-замок Ане́ — этапное произведение Французского Ренессанса, спроектированное Филибером Делормом. Немногочисленные элементы архитектурного комплекса, которые уцелели после Французской революции, расположены в департаменте Эр-э-Луар. Шато получило исключительную известность благодаря своей первой владелице — Диане де Пуатье. С 25 марта 1993 г. поместье обладает статусом памятника истории.","w":"https://ru.wikipedia.org/wiki/%D0%90%D0%BD%D0%B5"},"ch-Q1461848":{"n":"Шато-де-Феррье","r":"Шато-де-Феррье — французское шато, построенное с 1855 по 1859 год английским архитектором Джозефом Пакстоном по заказу Джеймса Майера Ротшильда. Право на владение шато передавалось по мужской линии по принципу первородства (примогенитура) до 1975 года, когда семья передала здание и земли Парижскому университету. Шато считается одним из крупнейших и богатейших замков XIX века и расположено на огромном участке земли в районе Феррье-ан-Бри департамента Сена и Марна, примерно в 26 км к востоку от Парижа.","w":"https://ru.wikipedia.org/wiki/%D0%A8%D0%B0%D1%82%D0%BE-%D0%B4%D0%B5-%D0%A4%D0%B5%D1%80%D1%80%D1%8C%D0%B5"},"ch-Q2007231":{"n":"Шато Миланд","r":"Шато де Мила́нд — шато в коммуне Кастельно-ла-Шапель в департаменте Дордонь. Расположено на высоком левом берегу реки Дордонь, возвышаясь на 50 метров над уровнем реки. В 2009 году вместе с парком и другими постройками внесено в список исторических памятников Франции. Среди бывших владельцев замка — производитель корсетов Огюст Клавери и певица Жозефина Бейкер.","w":"https://ru.wikipedia.org/wiki/%D0%9C%D0%B8%D0%BB%D0%B0%D0%BD%D0%B4_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1392601":{"n":"Отфор","r":"Замок д’Отфо́р — замок в стиле Ренессанс на западе Франции, построенный в XVII веке. Расположен в коммуне Отфор департамента Дордонь. Шато обрамляют террасы с французскими садами, где посадки самшита и цветы образуют геометрические мотивы.","w":"https://ru.wikipedia.org/wiki/%D0%9E%D1%82%D1%84%D0%BE%D1%80_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1436883":{"n":"Замок Монтенон","c":"Дворцово-замковый комплекс во Франции","r":"Ментенон — дворцово-замковый комплекс, построенный на месте бывшего средневекового замка. Расположен в коммуне Ментенон, в департаменте Эр и Луар в регионе Центр — Долина Луары, Франция. Наиболее известен как частная резиденция второй супруги короля Людовика XIV, мадам де Ментенон. Причём имя, под которым она вошла в историю, знаменитая француженка взяла после приобретения замка. В 1944 году комплекс был включён в список охраняемых исторических памятников Франции. По своему типу относится к замкам на воде.","w":"https://ru.wikipedia.org/wiki/%D0%9C%D0%B5%D0%BD%D1%82%D0%B5%D0%BD%D0%BE%D0%BD_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2241121":{"n":"Замок Фенелон","c":"Средневековый замок во Франции","r":"Фенелон — средневековый замок XII века во Франции. Расположен в коммуне Сен-Мондан в департаменте Дордонь, в регионе Новая Аквитания. В 1951 году внесён в список охраняемых объектов. По своему типу относится к замкам на вершине.","w":"https://ru.wikipedia.org/wiki/%D0%A4%D0%B5%D0%BD%D0%B5%D0%BB%D0%BE%D0%BD_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1765935":{"n":"Булонский замок","c":"замок в Париже","r":"Булонский замок, прозванный Мадрид или Мадридский замок, — ренессансная резиденция короля Франциска I в Булонском лесу под Парижем. Снесена в конце XVIII века.","w":"https://ru.wikipedia.org/wiki/%D0%91%D1%83%D0%BB%D0%BE%D0%BD%D1%81%D0%BA%D0%B8%D0%B9_%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA"},"ch-Q1789782":{"n":"Замок Канде","c":"замок во Франции на реке Эндр","r":"Замок Канде — замок во Франции, департамент Эндр и Луара.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%9A%D0%B0%D0%BD%D0%B4%D0%B5"},"ch-Q2418225":{"n":"Замок Витре","r":"Замок Витре — средневековый замок, расположенный в одноимённом историческом городе Бретани. Нынешний облик приобрёл в результате масштабной реконструкции XIX века.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%92%D0%B8%D1%82%D1%80%D0%B5"},"ch-Q1808966":{"n":"Замок Вильсавен","c":"Дворцово-замковый комплекс в Долине Луары","r":"Вильсавен — дворцово-замковый комплекс в коммуне Тур-ан-Солонь в департаменте Луар и Шер региона Долина Луары, Франция. Располагается на берегу реки Бёврон между замками Шамбор и Шеверни в области Солонь. Является одним из самых маленьких по площади замков Луары. С 1959 года комплекс включён в список Исторических памятников Франции.","w":"https://ru.wikipedia.org/wiki/%D0%92%D0%B8%D0%BB%D1%8C%D1%81%D0%B0%D0%B2%D0%B5%D0%BD_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2452513":{"n":"Вилла Эфрусси-де-Ротшильд","c":"достопримечательность","r":"Вилла Эфрусси-де-Ротшильд — вилла семейства Эфрусси, построенная на мысе Сен-Жан-Кап-Ферра Лазурного Берега баронессой Беатрисой Ротшильд в 1905—1912 годах.","w":"https://ru.wikipedia.org/wiki/%D0%92%D0%B8%D0%BB%D0%BB%D0%B0_%D0%AD%D1%84%D1%80%D1%83%D1%81%D1%81%D0%B8-%D0%B4%D0%B5-%D0%A0%D0%BE%D1%82%D1%88%D0%B8%D0%BB%D1%8C%D0%B4"},"ch-Q2971307":{"n":"Замок Мот-Шанденье","r":"Замок Мот-Шанденье — французский замок, который расположен возле города Ле Труа-Мутье, что на западе Франции, в департаменте Вьенна. Замок был построен в XIII веке, как семейная резиденция знатного рода Боссе, который подчинялся королю Франции. Изначально крепость называли — Мот Буссэ.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%9C%D0%BE%D1%82-%D0%A8%D0%B0%D0%BD%D0%B4%D0%B5%D0%BD%D1%8C%D0%B5"},"ch-Q2032139":{"n":"Замок Серран","c":"Дворцово-замковый комплекс в долине Луары во Франции","r":"Серран — дворцово-замковый комплекс, расположенный недалеко от города Сен-Жорж-сюр-Луар в департаменте Мен и Луара, в регионе Пеи-де-ла-Луар, Франция. Крепость создана как замок на воде.","w":"https://ru.wikipedia.org/wiki/%D0%A1%D0%B5%D1%80%D1%80%D0%B0%D0%BD_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q740250":{"n":"Замок Тараскон","r":"Замок короля Рене — основная достопримечательность города Тараскон в Провансе, расположена на берегу реки Роны, напротив города Бокер.","w":"https://ru.wikipedia.org/wiki/%D0%A2%D0%B0%D1%80%D0%B0%D1%81%D0%BA%D0%BE%D0%BD_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA_)"},"ch-Q769365":{"n":"Замок Монпупон","c":"Средневековый замок в долине Луары во Франции","r":"Монпупо́н — средневековый замок в департаменте Эндр и Луара, в центре Франции в регионе Долина Луары. Расположен к востоку от Тура и в 10 км к югу от Монришар. Монпупон находится всего в нескольких километрах от знаменитого замка Шенонсо. С января 1966 года комплекс Монпупон включён в число исторических памятников Франции.","w":"https://ru.wikipedia.org/wiki/%D0%9C%D0%BE%D0%BD%D0%BF%D1%83%D0%BF%D0%BE%D0%BD_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1013196":{"n":"Замак Нажак","c":"Руины Средневекового замка на юге Франции","r":"Нажак — руины средневекового замка в коммуне Нажак, в департаменте Аверон в регионе Окситания, Франция. Комплекс возведён между 1253 и 1266 годами по приказу Альфонса де Пуатье, брата короля Людовика IX. Ранее на этом месте уже существовали каменные укрепления. Первым крепость в романском стиле на высоком холме построил около 1100 года Бертран де Сен-Жиль, сын Раймунда IV Тулузского. Нажак принадлежал к числу королевских замков. Руины замка 3 июля 1925 года были объявлены во Франции историческим памятником. По своему типу относится к замкам на вершине.","w":"https://ru.wikipedia.org/wiki/%D0%9D%D0%B0%D0%B6%D0%B0%D0%BA_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1013993":{"n":"Седан (замок)","r":"Седанская крепость — мощная средневековая крепость в Седане, на скальном уступе долины Мааса, между реками Бьевр и Вра, во французском департаменте Арденны, около границы с Бельгией. Одна из крупнейших крепостей Западной Европы, занимает площадь 35 000 квадратных метров и имеет семь этажей.","w":"https://ru.wikipedia.org/wiki/%D0%A1%D0%B5%D0%B4%D0%B0%D0%BD%D1%81%D0%BA%D0%B0%D1%8F_%D0%BA%D1%80%D0%B5%D0%BF%D0%BE%D1%81%D1%82%D1%8C"},"ch-Q638089":{"n":"Плесси-ле-Тур","r":"Плесси-ле-Тур — остатки королевской резиденции (шато) в местечке Ла-Риш, пригороде Тура. Один из многочисленных позднеготических замков долины Луары.","w":"https://ru.wikipedia.org/wiki/%D0%9F%D0%BB%D0%B5%D1%81%D1%81%D0%B8-%D0%BB%D0%B5-%D0%A2%D1%83%D1%80"},"ch-Q654569":{"n":"Монтрёй-Белле","r":"Монтрёй-Белле — средневековый замок.","w":"https://ru.wikipedia.org/wiki/%D0%9C%D0%BE%D0%BD%D1%82%D1%80%D1%91%D0%B9-%D0%91%D0%B5%D0%BB%D0%BB%D0%B5_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1339136":{"n":"Гресильон","c":"Замок и культурный центр эсперанто во Франции","r":"Гресильон — культурный центр эсперантистов Франции, занимающий усадьбу (шато) в местечке Боже-ан-Анжу, в 30 км от Анжера. Усадьба принадлежит некоммерческой организации «Культурный дом Эсперанто».","w":"https://ru.wikipedia.org/wiki/%D0%93%D1%80%D0%B5%D0%B7%D0%B8%D0%BB%D1%8C%D0%BE%D0%BD"},"ch-Q1462683":{"n":"Замок Рео","r":"Замок Рео или Ле-Рео — один из ренессансных замков Луары. Расположен в Турени, в посёлке Шузе-сюр-Луар кантона Бургей, департамент Эндр и Луара.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%A0%D0%B5%D0%BE"},"ch-Q1518981":{"n":"Замок Пимартен","r":"Замок Пюимарте́н — средневековый замок, расположенный на территории коммуны Марке в департаменте Дордонь региона Новая Аквитания (Франция).","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%9F%D1%8E%D0%B8%D0%BC%D0%B0%D1%80%D1%82%D0%B5%D0%BD"},"ch-Q1579344":{"n":"замок Со"},"ch-Q1859459":{"n":"Замок Ла-Бред","r":"Замок Ла-Бред располагается в коммуне Ла-Бред французского департамента Жиронда. В 1689 году здесь родился писатель и мыслитель Монтескьё. В замке были написаны большинство его трудов. 7 мая 2008 года всему архитектурному ансамблю был присвоен статус исторического памятника.","w":"https://ru.wikipedia.org/wiki/%D0%9B%D0%B0-%D0%91%D1%80%D0%B5%D0%B4_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1789926":{"n":"Замок Флер","r":"Флер — усадебный дом в местечке Вильнёв-д’Аск на северо-востоке Франции, у самой границы с Бельгией. Он был построен в 1660-е годы в характерном для помещичьих домов Испанских Нидерландов стиле. До 1747 года принадлежал дворянскому семейству де Кассель, которое владело ближайшей деревней Флер. В XXI веке замок делят небольшой краеведческий музей и отдел городской администрации по туризму.","w":"https://ru.wikipedia.org/wiki/%D0%A4%D0%BB%D0%B5%D1%80_(%D1%83%D1%81%D0%B0%D0%B4%D1%8C%D0%B1%D0%B0)"},"ch-Q2206135":{"n":"Замок де Бонагёй","c":"Крупный замковый комплекс во Франции","r":"Бонагёй — средневековый каменный замок во Франции. Расположен в коммуне Сен-Фрон-сюр-Леманс, но административно принадлежит коммуне Фюмель. Находится в департаменте Ло и Гаронна на самой границе с историческими областями Аженуа и Керси, в регионе Новая Аквитания. Возведён в XIII веке и значительно перестроен в XV веке. В 1862 году внесён в список исторических памятников Франции. По своему типу относится к замкам на вершине.","w":"https://ru.wikipedia.org/wiki/%D0%91%D0%BE%D0%BD%D0%B0%D0%B3%D1%91%D0%B9_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2259452":{"n":"Замок Анси"},"ch-Q2970742":{"n":"Замок Сусиньо","c":"Старинный замок во французском регионе Бретань","r":"Сусиньо — средневековый замок на полуострове Руйс на берегу Атлантического океана в коммуне Сарзо, в департаменте Морбиан, в регионе Бретань, Франция. Замок долгое время был главной резиденцией герцогов Бретани. Некогда вокруг лежали обширные леса. В настоящее время замок окружён в основном солончаками и лугами.","w":"https://ru.wikipedia.org/wiki/%D0%A1%D1%83%D1%81%D0%B8%D0%BD%D1%8C%D0%BE_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1090405":{"n":"Шато Шваль Блан","r":"Шато Шеваль-Блан — французское винодельческое хозяйство, расположенное в коммуне Сент-Эмильон, департамент Жиронда, регион Новая Аквитания. Относится к винодельческому региону Бордо, субрегион Либурне. Виноградники граничат с Померолем.","w":"https://ru.wikipedia.org/wiki/%D0%A8%D0%B0%D1%82%D0%BE_%D0%A8%D0%B5%D0%B2%D0%B0%D0%BB%D1%8C-%D0%91%D0%BB%D0%B0%D0%BD"},"ch-Q657892":{"n":"Замок Люд","c":"Дворцово-замковый комплекс во Франции","r":"Люд — дворцово-замковый комплекс во Франции. Расположен в коммуне Ле-Люд, в департаменте Сарта, в регионе Пеи-де-ла-Луар. Принадлежит к группе северных замков долины Луары. Первые крепления в этом месте появились в IX веке. В годы Столетней войны замок захватили англичане. В 1457 году Люд стал собственностью Жана Дайона, камергера короля Людовика XI. В последующие два столетия представители семьи Даойн превратили суровую средневековую крепость в роскошную резиденцию. Замок был значительно перестроен в конце XVIII века маркизой де ла Вьевиль. Столетием позже реконструкцию провёл политик Огюст де Тальуэ-Рой.","w":"https://ru.wikipedia.org/wiki/%D0%9B%D1%8E%D0%B4_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1815574":{"n":"Биронский замок","r":"Замок Бирон — замок во французской коммуне Бирон в департаменте Дордонь региона Аквитания. Замок расположен на границе между историческими провинциями Перигор и Ажене и справедливо считается самым значительным замком современного департамента Дордонь. Редкий, возможно, единственный пример нахождения феода во владении одного рода на протяжении 24 поколений семьи Гонто, с XII века по 1938 год. Именно благодаря такой продолжительной преемственной семье удалось построить очень гармоничный архитектурный комплекс, несмотря на прошедшие исторические потрясения и немысленное наслоение построек в разных архитектурных стилях.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%91%D0%B8%D1%80%D0%BE%D0%BD"},"ch-Q2450180":{"n":"Басти д'Юрфе","r":"Басти́ д’Юрфе́ — замок во французском департаменте Луара, открытый для туристов; место летних спектаклей «Бастийские ночи». В нём когда-то жил французский писатель Оноре д’Юрфе, автор пасторального романа «Астрея».","w":"https://ru.wikipedia.org/wiki/%D0%91%D0%B0%D1%81%D1%82%D0%B8_%D0%B4%E2%80%99%D0%AE%D1%80%D1%84%D0%B5"},"ch-Q2501434":{"n":"Дворец в Э","c":"дворец на севере Франции","r":"Шато-д’Э — королевский дворец в городе Э на севере Франции, в 4 км от Ла-Манша. Построен герцогом Генрихом Гизом и его супругой, Екатериной Клевской, в конце XVI века на месте замка, разрушенного в 1475 году во избежание его взятия англичанами. Свой нынешний вид дворец приобрёл в XVII веке, когда его обитательницей была герцогиня де Монпансье. Король Луи-Филипп превратил шато д’Э в свою летнюю резиденцию; дважды он принимал в нём английскую королеву Викторию. С 1973 года во дворце размещается музей Луи-Филиппа и его эпохи.","w":"https://ru.wikipedia.org/wiki/%D0%94%D0%B2%D0%BE%D1%80%D0%B5%D1%86_%D0%B2_%D0%AD"},"ch-Q197482":{"n":"Замок Роше-Севинье","r":"Роше-Севинье — замок (шато) в городе Витре.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%A0%D0%BE%D1%88%D0%B5-%D0%A1%D0%B5%D0%B2%D0%B8%D0%BD%D1%8C%D0%B5"},"ch-Q1011985":{"n":"Жизорский замок","r":"Жизорский замок часто называют замком тамплиеров. Учёные до сих пор спорят, является ли холм, на котором построен замок Жизор, естественным или искусственным, но стратегическое положение замка бесспорно.","w":"https://ru.wikipedia.org/wiki/%D0%96%D0%B8%D0%B7%D0%BE%D1%80%D1%81%D0%BA%D0%B8%D0%B9_%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA"},"ch-Q1090706":{"n":"Фор-де-Жу"},"ch-Q1190649":{"n":"Монте-Кристо","r":"Монте-Кри́сто — французская усадьба (шато) в Порт-Марли, отстроенная Александром Дюма в 1847 г. на средства от публикации романа «Граф Монте-Кристо». Проект разработан архитектором Ипполитом Дюраном.","w":"https://ru.wikipedia.org/wiki/%D0%9C%D0%BE%D0%BD%D1%82%D0%B5-%D0%9A%D1%80%D0%B8%D1%81%D1%82%D0%BE_(%D1%83%D1%81%D0%B0%D0%B4%D1%8C%D0%B1%D0%B0)"},"ch-Q976038":{"n":"Монжоффруа","r":"Монжоффруа — усадьба маршала Контада в долине Луары, департамент Мен и Луара. Усадебный дом в Монжоффруа был построен в виде подковы. Современный вид приобрёл в конце XVIII века. Монжоффруа — одно из трех луарских шато, сохранивших внутреннюю обстановку, передававшуюся от поколения к поколению.","w":"https://ru.wikipedia.org/wiki/%D0%9C%D0%BE%D0%BD%D0%B6%D0%BE%D1%84%D1%84%D1%80%D1%83%D0%B0"},"ch-Q1010879":{"n":"Арк (замок)","r":"Арк — средневековый замок, построенный в XIII веке. Расположен в коммуне Арк, в кантоне Куиза, в департаменте Од, в историческом регионе Окситания, Франция. Признан охраняемым памятником архитектуры. По своему типу относится к замкам на вершине. Входил в состав системы катарских замков.","w":"https://ru.wikipedia.org/wiki/%D0%90%D1%80%D0%BA_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1517348":{"n":"Шатонёф","r":"За́мок Шатонёф — крепость, построенная в XI веке и перестроенная в XV веке, находящаяся в коммуне Шатонёф, департамент Кот-д’Ор, Франция, находится в 43 километрах от Дижона. Представляет собой крупное каменное здание, имеет 75 метров в длину и 35 метров в ширину. Замок расположен в долине Бургундского канала на каменном выступе на высоте 475 метров над прилегающей поверхностью.","w":"https://ru.wikipedia.org/wiki/%D0%A8%D0%B0%D1%82%D0%BE%D0%BD%D1%91%D1%84_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1650661":{"n":"Замок Комбур","c":"Средневековый замок в Бретани, Франция","r":"Комбур — средневековый замок, расположенный на территории коммуны Комбур, в департаменте Иль и Вилен, в регионе Бретань, Франция. Ещё в 1926 году основная часть сооружения была отнесена к историческим памятникам. А в августе 1966 года весь комплекс признали памятником.","w":"https://ru.wikipedia.org/wiki/%D0%9A%D0%BE%D0%BC%D0%B1%D1%83%D1%80_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2968843":{"n":"Шамероль (замок, Франция)","r":"Шамероль — старинный замок в стиле Ренессанса в коммуне Шильё-о-Буа, в департаменте Луаре в регионе Центр — Долина Луары, Франция. Является одним из комплексов, который признан составной частью популярного туристического маршрута замков Луары. В 1927 году объект получил статус памятника архитектуры Франции. По своему типу относится к замкам на воде.","w":"https://ru.wikipedia.org/wiki/%D0%A8%D0%B0%D0%BC%D0%B5%D1%80%D0%BE%D0%BB%D1%8C_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q3361199":{"n":"Идеальный дворец","c":"Памятник Наивной архитектуры во Франции","r":"Идеальный дворец — крупное сооружение, построенное почтальоном по имени Фердинанд Шеваль в период с 1879 по 1912 год. Находится в коммуне Отрив, в департаменте Дром, в регионе Овернь — Рона — Альпы, Франция. Считается шедевром наивной архитектуры и наивного искусства. В 1969 году дворец внесён в список исторических памятников Франции.","w":"https://ru.wikipedia.org/wiki/%D0%98%D0%B4%D0%B5%D0%B0%D0%BB%D1%8C%D0%BD%D1%8B%D0%B9_%D0%B4%D0%B2%D0%BE%D1%80%D0%B5%D1%86_(%D0%A4%D1%80%D0%B0%D0%BD%D1%86%D0%B8%D1%8F)"},"ch-Q1989567":{"n":"Замок Гайон","c":"Замок-дворец эпохи Возрождения","r":"Замок Гайон — замок-дворец эпохи Возрождения, построенный на месте средневековой крепости, во французской коммуне Гайон на территории департамента Эр. Первый во Франции дворец в стиле Возрождения. После Французской революции замок почти полностью реконструирован под пенитенциарное учреждение. Объект классифицирован как национальный исторический памятник Франции.","w":"https://ru.wikipedia.org/wiki/%D0%93%D0%B0%D0%B9%D0%BE%D0%BD_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2971472":{"n":"Замок Ле-Бо","c":"Замок в провинции Прованс (Франция)","r":"Замок Ле-Бо — средневековая крепость в Южном Провансе. Вместе с расположенной чуть ниже по склону деревней Бо-де-Прованс является одной из главных достопримечательностей Прованса.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%9B%D0%B5-%D0%91%D0%BE"},"ch-Q2095479":{"n":"Клермон","c":"исторический памятник зарегистрированный - Атлантическая Луара, Ансени","r":"Клермон — усадьба (шато) с господским домом, построенным между 1643 и 1649 годами близ коммуны Селье, в департаменте Атлантическая Луара, на расстоянии 27 км от города Нант во Франции. Усадьба принадлежала Леону Мопассану, однофамильцу писателя Ги де Мопассана, прежде чем стать собственностью актёра Луи де Фюнеса, который был последним её обитателем.","w":"https://ru.wikipedia.org/wiki/%D0%9A%D0%BB%D0%B5%D1%80%D0%BC%D0%BE%D0%BD_(%D1%83%D1%81%D0%B0%D0%B4%D1%8C%D0%B1%D0%B0)"},"ch-Q2476068":{"n":"Замок Танле","c":"Ренессансный замок во Франции","r":"Замок Танле́ — ренессансный замковый комплекс на месте средневековой крепости во Франции. Расположен в одноимённой коммуне, в округе Авалон, в департаменте Йонна, в северной части исторического региона Бургундия, ныне — регион Бургундия — Франш-Конте. Находится к востоку от городка Тоннера и примерно в 20 километрах к северо-востоку от Нуайе. По своему типу относится к замкам на воде. В 1994 году признан памятником архитектуры Франции.","w":"https://ru.wikipedia.org/wiki/%D0%A2%D0%B0%D0%BD%D0%BB%D0%B5_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q282646":{"n":"Сент-Юльрик (замок, Франция)","r":"Сент-Юльрик — руины средневекового замка, которые возвышаются над коммуной Рибовилле в департаменте Верхний Рейн, в регионе Гранд-Эст, Франция. Также можно встретить такие названия как Гран-Рибопьер или Раппольштейн. Является одним из трёх замков, находящихся в зоне видимости друг друга. Расположен на высоте 528 метров над уровнем моря. Ещё в 1841 году руины замка были отнесены к историческим памятникам. В феврале 1930 года этот статус был подтверждён. По своему типу относится к замкам на вершине.","w":"https://ru.wikipedia.org/wiki/%D0%A1%D0%B5%D0%BD%D1%82-%D0%AE%D0%BB%D1%8C%D1%80%D0%B8%D0%BA_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q752990":{"n":"шато Бальруа"},"ch-Q637019":{"n":"Замок Анжони","r":"За́мок Анжони́ — французский замок XV—XVIII веков в городе Турнемир департамента Канталь.","w":"https://ru.wikipedia.org/wiki/%D0%90%D0%BD%D0%B6%D0%BE%D0%BD%D0%B8_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1333383":{"n":"Замок Монтень","r":"Замок Монтень — резиденция французского философа Мишеля де Монтеня в коммуне Сен-Мишель-де-Монтень. Историческое здание было сооружено в XIV веке, и сильно пострадало от пожара в 1885 году. Башня с кабинетом Монтеня в 1952 году получила статус исторического памятника, остальная часть замка и парк — в 2009 году.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%9C%D0%BE%D0%BD%D1%82%D0%B5%D0%BD%D1%8C"},"ch-Q1476690":{"n":"Отель Сен-Поль","c":"дворец, резиденция французских королей"},"ch-Q1552130":{"n":"Замок Бюсси-Рабютен","c":"Ренессансный замок во Франции","r":"Бюсси-Рабютен или Бюсси-ле-Гран — ренессансный замковый комплекс во Франции. Расположен в коммуне Бюсси-ле-Гран в департаменте Кот-д’Ор, в северной части исторического региона Бургундия, ныне — регион Бургундия — Франш-Конте. По своему типу относится к замкам на воде. Ещё в 1862 году признан памятником архитектуры Франции. Находится в ведении Национального центра памятников при Министерстве культуры.","w":"https://ru.wikipedia.org/wiki/%D0%91%D1%8E%D1%81%D1%81%D0%B8-%D0%A0%D0%B0%D0%B1%D1%8E%D1%82%D0%B5%D0%BD_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2971586":{"n":"Шато-Шамбери"},"ch-Q2971835":{"n":"Форт Торо","r":"Форт Торо — крепость, расположенная на скалистом островке в заливе Морле пролива Ла-Манш.","w":"https://ru.wikipedia.org/wiki/%D0%A4%D0%BE%D1%80%D1%82_%D0%A2%D0%BE%D1%80%D0%BE"},"ch-Q2675627":{"n":"Замок Пуансе","r":"Замок Пуансе — второй по величине средневековый замок Анжу. Расположен в долине реки Верзе, выше города Пуансе, в 16 километрах восточнее Шатобриана, в так называемом Четырёхугольнике, образованном городами Ренн, Лаваль, Анжер и Нант. Развалины внесены в список исторических памятников Франции.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%9F%D1%83%D0%B0%D0%BD%D1%81%D0%B5"},"ch-Q161787":{"n":"Шан-сюр-Марн","r":"Шан-сюр-Марн — небольшой загородный дворец времён Людовика XIV на берегу Марны в одноимённом предместье Парижа. Дворец построен в 1699—1706 годах иждивением двух финансистов, Ш. Р. де Латуана и П. Пуассон де Бурвале, по проекту отца и сына Булле. Регулярный усадебный парк устроил в 1710 году Клод Дего, племянник Ленотра.","w":"https://ru.wikipedia.org/wiki/%D0%A8%D0%B0%D0%BD-%D1%81%D1%8E%D1%80-%D0%9C%D0%B0%D1%80%D0%BD_(%D0%B4%D0%B2%D0%BE%D1%80%D0%B5%D1%86)"},"ch-Q1012942":{"n":"крепость Лихтенберг","c":"руины в эльзасском Лиштенберге"},"ch-Q947669":{"n":"Мулен (замок)","r":"Мулен — средневековый замок во Франции. Возведён в XV веке. Расположен в коммуне Лассе-сюр-Круан, в департаменте Луар и Шер, в округе Ле-Блан, в историческом регионе Центр — Долина Луары. В 1926 году признан охраняемым памятником архитектуры. По своему типу относится к замкам на воде.","w":"https://ru.wikipedia.org/wiki/%D0%9C%D1%83%D0%BB%D0%B5%D0%BD_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2242003":{"n":"Замок Ла Бюссьер","r":"Замок Ла Бюссьер — замок на воде на окраине французского округа Ла Бюссьер в регионе Центр — Долина Луары. Стоит приблизительно в 10 км к северо-востоку от Жьена, на юго-востоке департамента Луаре. Замок относится к Замкам Луары и стоит на Пути Жака Кёра. С ноября 1993 года некоторые части замка вошли в список исторических памятников Франции. В мае 1995 года другие части замка, находившиеся в частной собственности, также объявлены историческими памятниками.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%9B%D0%B0_%D0%91%D1%8E%D1%81%D1%81%D1%8C%D0%B5%D1%80"},"ch-Q2969865":{"n":"Замок Мовзен","c":"Средневековый замок во Франции","r":"Мовзен — средневековый замок, расположенный в коммуне Мовзен недалеко от города Капверн в департаменте Верхние Пиренеи, в регионе Окситания, Франция. По своему типу относится к замкам на вершине. Комплекс полностью отреставрирован и открыт для посещения в течение всего года.","w":"https://ru.wikipedia.org/wiki/%D0%9C%D0%BE%D0%B2%D0%B7%D0%B5%D0%BD_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2970548":{"n":"Сен-Мало (крепость, Франция)","r":"Сен-Мало — крепость в городе Сен-Мало, в регионе Бретань, Франция. Замок был построен герцогами Бретани, чтобы обеспечить контроль над своенравными жителями города Сен-Мало, который был важнейшим портом в их владениях. В июле 1886 года крепость была включена в список исторических памятников Франции.","w":"https://ru.wikipedia.org/wiki/%D0%A1%D0%B5%D0%BD-%D0%9C%D0%B0%D0%BB%D0%BE_(%D0%BA%D1%80%D0%B5%D0%BF%D0%BE%D1%81%D1%82%D1%8C)"},"ch-Q3361032":{"n":"Дворец правосудия в Пуатье","r":"Дворец правосудия в Пуатье — резиденция графов де Пуатье и герцогов Аквитании в X—XII веках.","w":"https://ru.wikipedia.org/wiki/%D0%94%D0%B2%D0%BE%D1%80%D0%B5%D1%86_%D0%BF%D1%80%D0%B0%D0%B2%D0%BE%D1%81%D1%83%D0%B4%D0%B8%D1%8F_%D0%B2_%D0%9F%D1%83%D0%B0%D1%82%D1%8C%D0%B5"},"ch-Q3361183":{"n":"Дворец римского короля","r":"Дворец римского короля — дворец, который предназначался стать резиденцией Наполеона II, титулованного римского короля и сына Наполеона Бонапарта. Огромное здание должно было стоять на месте нынешнего дворца Шайо в XVI округе Парижа. Величественный и красивый, дворец должен был стать украшением города. Амбициозные планы и падение Империи привели к тому, что дворец так и не был построен. Его архитектор Пьер Фонтен заявлял, что дворец мог бы стать «самым обширным и самым экстраординарным зданием нашего века».","w":"https://ru.wikipedia.org/wiki/%D0%94%D0%B2%D0%BE%D1%80%D0%B5%D1%86_%D1%80%D0%B8%D0%BC%D1%81%D0%BA%D0%BE%D0%B3%D0%BE_%D0%BA%D0%BE%D1%80%D0%BE%D0%BB%D1%8F"},"ch-Q2969479":{"n":"Замок Кержан","c":"Ренессансный замковый комплекс во Франции","r":"Тюрпо — ренессансный замок во Франции. Комплекс расположен в коммуне Сен-Вуге, в департаменте Финистер, в регионе Бретань. Классифицирован как исторический памятник указом 29 апреля 1911 года. Является одним из лучших образцов эпохи Возрождения в исторической области Бретань. Замок находится в государственной собственности. Непосредственным управлением занимаются власти департамента Финистер через специальный фонд EPCC Chemin du patrimoine en Finistère. По своему типу Кержан относится к замкам на воде.","w":"https://ru.wikipedia.org/wiki/%D0%9A%D0%B5%D1%80%D0%B6%D0%B0%D0%BD_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2422758":{"n":"Замок Шаваньяк","r":"Замок Шаваньяк-Лафайет — французский укреплённый дом XIV—XVIII веков. В этом замке родился маркиз де Лафайет, здесь находится его музей. Замок расположен в коммуне Шаваньяк-Лафайет, в 92 км к юго-востоку от Клермон-Феррана, между Бриудом и Ле-Пюи-ан-Веле.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%A8%D0%B0%D0%B2%D0%B0%D0%BD%D1%8C%D1%8F%D0%BA"},"ch-Q2968329":{"n":"Château d'Osthoffen"},"ch-Q2242766":{"n":"Замок О","c":"Старинный замок во Франции","r":"О — замок XV века во Франции. Расположен в коммуне Мортре, в департаменте Орн, в регионе Нормандия. По своему типу относится к замкам на воде. Комплекс многократно перестраивался. Сооружение признано историческим памятником Франции.","w":"https://ru.wikipedia.org/wiki/%D0%9E_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2321914":{"n":"Куранс (замок)","r":"Замок Куранс — историческое здание и парк в Курансе, департамент Эсон в Иль-де-Франс на севере Франции к юго-востоку от Парижа. 27 июня 1983 года ансамбль замка признан историческим памятником Франции.","w":"https://ru.wikipedia.org/wiki/%D0%9A%D1%83%D1%80%D0%B0%D0%BD%D1%81_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q600832":{"n":"Шато-де-Гулен","r":"Гулен — замок XV-XVII веков и винодельня (шато) в долине Луары, в коммуне От-Гулен. Некоторые источники позиционируют его как старейшее винодельческое хозяйство в мире. Замок Гулен с 1913 года классифицируется как исторический памятник.","w":"https://ru.wikipedia.org/wiki/%D0%93%D1%83%D0%BB%D0%B5%D0%BD_(%D1%83%D1%81%D0%B0%D0%B4%D1%8C%D0%B1%D0%B0)"},"ch-Q1014739":{"n":"Этамп","c":"замок"},"ch-Q1117166":{"n":"замок Аруэ","c":"замок в Лотарингии, Франция","r":"Замок Аруэ — резиденция (шато) Марка де Бово-Краона, наместника Лотарингии, возведённая в 1720-1732 годах по проекту архитектора Жермена Бофрана в местечке Аруэ, в 25 км южнее Нанси. Другие названия — дворец Аруэ и замок Бово-Краон. В списке исторических памятников с 1983 года.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%90%D1%80%D1%83%D1%8D"},"ch-Q1090652":{"n":"Шато Розан-Сегла","c":"французское винодельческое хозяйство","r":"Шато Роза́н-Сегла́ — французское винодельческое хозяйство, расположенное в Марго, по соседству с винодельней Шато Розан-Гасси. Виноградники находятся в регионе Бордо, на левом берегу Гаронны, в субрегионе Медока Верхний Медок.","w":"https://ru.wikipedia.org/wiki/%D0%A8%D0%B0%D1%82%D0%BE_%D0%A0%D0%BE%D0%B7%D0%B0%D0%BD-%D0%A1%D0%B5%D0%B3%D0%BB%D0%B0"},"ch-Q905650":{"n":"замок д'Уарон"},"ch-Q948136":{"n":"Замок Рамбюр","c":"Средневековый каменный замок во Франции","r":"Рамбюр — старинный замок во Франции, один из наиболее хорошо сохранившихся средневековых фортификационных комплексов XV века. Расположен в одноимённой коммуне, в департаменте Сомма, в регионе О-де-Франс. За время существования ни разу не был взят штурмом или в ходе осады. По своему типу относится к замкам на равнине.","w":"https://ru.wikipedia.org/wiki/%D0%A0%D0%B0%D0%BC%D0%B1%D1%8E%D1%80_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q951768":{"n":"Замок Визиль"},"ch-Q1011343":{"n":"Кастельбу","r":"Замок Кастельбук — разрушенный замок в Тарнском ущелье неподалёку от Сент-Эними в департаменте Лозер (Лангедок-Руссильон).","w":"https://ru.wikipedia.org/wiki/%D0%9A%D0%B0%D1%81%D1%82%D0%B5%D0%BB%D1%8C%D0%B1%D1%83%D0%BA"},"ch-Q1011407":{"n":"Кюлан (замок)"},"ch-Q2242009":{"n":"Ла-Мот-Тийи","r":"Ла-Мот-Тийи или Ла-Мот-Тилли — типичное шато времён Людовика XV, выстроенное в 1754-55 годах в деревне Ла-Мот-Тийи. Усадьба находится на левом берегу Сены, в 7 километрах от города Ножан-сюр-Сен, и включает господский дом и несколько десятков гектаров лесопарковой зоны.","w":"https://ru.wikipedia.org/wiki/%D0%9B%D0%B0-%D0%9C%D0%BE%D1%82-%D0%A2%D0%B8%D0%B9%D0%B8_(%D1%83%D1%81%D0%B0%D0%B4%D1%8C%D0%B1%D0%B0)"},"ch-Q2242114":{"n":"Шан-де-Батай","r":"Шан-де-Батай — дворцово-парковый комплекс (шато) во французской коммуне Сент-Оппортюн-дю-Боск, в департаменте Эр административного региона Верхняя Нормандия. Небольшой дворец с парком построили в XVII веке для маршала Франуса де Креки.","w":"https://ru.wikipedia.org/wiki/%D0%A8%D0%B0%D0%BD-%D0%B4%D0%B5-%D0%91%D0%B0%D1%82%D0%B0%D0%B9"},"ch-Q2240222":{"n":"Замок Бомениль","r":"Замок Бомениль — замок во французской коммуне Бомениль, департамента Эр, региона Верхняя Нормандия. Редкий пример загородной резиденции эпохи Людовика XIII, построен для маркиза де Нонана. С 1927 по 1939 год принадлежал великому князю Дмитрию Павловичу (1891—1942) из династии Романовых. Часть дворца и парка в 1966 году классифицирована как национальный исторический памятник.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%91%D0%BE%D0%BC%D0%B5%D0%BD%D0%B8%D0%BB%D1%8C"},"ch-Q2968565":{"n":"Замок Бити","r":"Замок Бити — небольшой замок XVI века с 20 гектарами угодий на малой родине Жака Ширака в небольшой коммуне Сарран южнофранцузского департамента Коррез, в 10 км к востоку от Тюля, недалеко от автострады A89; принадлежит чете Ширак. Памятник истории с 1969 года.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%91%D0%B8%D1%82%D0%B8"},"ch-Q2969584":{"n":"Замок Ла-Рошфуко","c":"Ренессансный замок во Франции","r":"Ла-Рошфуко — Ренессансный замок во Франции. Расположен на берегу реки Тардуар в одноимённой коммуне, в департаменте Шаранта, в исторической области Пуату — Шарант, в регионе Новая Аквитания. Комплекс возведён около 1520 года на месте средневековой крепости XI века. От этого сооружения сохранились башни, которые встроили в новое сооружение. В 1955 году Ла-Рошфуко внесён в список исторических памятников Франции. На протяжении всей своей истории принадлежал старинному аристокартическому роду Ларошфуко. По своему типу относится к замкам на вершине.","w":"https://ru.wikipedia.org/wiki/%D0%9B%D0%B0-%D0%A0%D0%BE%D1%88%D1%84%D1%83%D0%BA%D0%BE_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA%2C_%D0%A8%D0%B0%D1%80%D0%B0%D0%BD%D1%82%D0%B0)"},"ch-Q2970867":{"n":"Замок Трекессон","c":"Средневековый каменный замок на воде в регионе Бретань во Франции","r":"Трекессон — средневековый замок, расположенный в городе Кампенеак, на окраине коммуны Гер, в департаменте Морбиан, в регионе Бретань, Франция. Является одним из самых впечатляющих замков региона Бретань. По своему типу относится к замкам на воде. Комплекс остаётся в частной собственности. В июне 1922 г замок включён в список исторических памятников Франции. В 2014 году этот статус распространён на окрестности замка.","w":"https://ru.wikipedia.org/wiki/%D0%A2%D1%80%D0%B5%D0%BA%D0%B5%D1%81%D1%81%D0%BE%D0%BD_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2740328":{"n":"Замок Монбрён","c":"Средневековый замок во Франции","r":"Монбрён — средневековый замок в коммуне Дурназак, во департаменте Верхняя Вьенна, в регионе Новая Аквитания, Франция. Возведён в XII веке. Позднее серьёзно перестроен. Остаётся в частной собственности. По своему типу относится к замкам на воде.","w":"https://ru.wikipedia.org/wiki/%D0%9C%D0%BE%D0%BD%D0%B1%D1%80%D1%91%D0%BD_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA%2C_%D0%92%D0%B5%D1%80%D1%85%D0%BD%D1%8F%D1%8F_%D0%92%D1%8C%D0%B5%D0%BD%D0%BD%D0%B0)"},"ch-Q2744196":{"n":"Замок Жумийяк","c":"Дворцово-замковая резиденция во Франции","r":"Жюмийяк — средневековый замок XIII века во Франции. В XVII веке полностью перестроен. Расположен в коммуне Жюмийьяк-ле-Гран в департаменте Дордонь, в регионе Новая Аквитания. Внесён в список охраняемых объектов. Находится в частной собственности, но открыт для посещения. По своему типу относится к замкам на вершине.","w":"https://ru.wikipedia.org/wiki/%D0%96%D1%8E%D0%BC%D0%B8%D0%B9%D1%8F%D0%BA_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2749729":{"n":"Шато де Блен"},"ch-Q2243758":{"n":"Замок Турнон"},"ch-Q2970324":{"n":"Замок Пюигийем","c":"Замок XVI века во Франции","r":"Пюигийем — Ренессансный каменный замок во Франции. Расположен в коммуне Виллар, в кантоне Брантом, в департаменте Дордонь, в регионе Новая Аквитания. Построен в XV веке. В 1912 году внесён в список исторических памятников Франции. По своему типу относится к замкам на вершине.","w":"https://ru.wikipedia.org/wiki/%D0%9F%D1%8E%D0%B8%D0%B3%D0%B8%D0%B9%D0%B5%D0%BC_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA%2C_%D0%92%D0%B8%D0%BB%D0%BB%D0%B0%D1%80)"},"ch-Q2968472":{"n":"Замок Бофор","r":"Бофо́р — замок во Франции в коммуне Гуде в долине реки Луары. Второй по возрасту замок в бассейне Луары.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%91%D0%BE%D1%84%D0%BE%D1%80_(%D0%92%D0%B5%D1%80%D1%85%D0%BD%D1%8F%D1%8F_%D0%9B%D1%83%D0%B0%D1%80%D0%B0)"},"ch-Q2968405":{"n":"Багатель (замок)","r":"Замок Багатель — малый загородный дворец, павильон для отдыха, или «причудливое сооружение», построенное в 1777 году архитектором Франсуа-Жозефом Беланже для графа Артуа, младшего брата Людовика XVI в Булонском лесу, ныне присоединенном к Парижу. Павильон, за исключением хозяйственных построек, был внесён в список исторических памятников указом от 31 января 1978 года и подтверждён более полным указом от 20 декабря 2022 года.","w":"https://ru.wikipedia.org/wiki/%D0%91%D0%B0%D0%B3%D0%B0%D1%82%D0%B5%D0%BB%D1%8C_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2969067":{"n":"замок Бонневаль","c":"замок в департаменте Верхняя Вьенна (Франция)","r":"Замок Бонневаль расположен в коммуне Куссак-Боннваль в департаменте Верхняя Вьена во Франции.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%91%D0%BE%D0%BD%D0%BD%D0%B5%D0%B2%D0%B0%D0%BB%D1%8C"},"ch-Q2969088":{"n":"Замок Крёлли","r":"Крёлли — замок в муниципалитете Крёлли, департаменте Кальвадос на северо-западе Франции. Расположен на правому крутом берегу реки Сель. Сооружен в XI—XII столетиях.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%9A%D1%80%D1%91%D0%BB%D0%BB%D0%B8"},"ch-Q3146116":{"n":"Ангулемский замок","r":"Ангулемский замок — замок в городе Ангулем в департаменте Шаранта. Единственные сохранившиеся его части — крепость-донжон Лузиньяна и башня Валуа. В XIX веке к ним была пристроена ратуша в неоготическом стиле с элементами Ренессанса и классицизма, сегодня — мэрия Ангулема.","w":"https://ru.wikipedia.org/wiki/%D0%90%D0%BD%D0%B3%D1%83%D0%BB%D0%B5%D0%BC%D1%81%D0%BA%D0%B8%D0%B9_%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA"},"ch-Q2970802":{"n":"Замок Тури","c":"Средневековый замок во Франции","r":"Тури — средневековый замок во Франции. Расположен в коммуне Сен-Пурсен-сюр-Бебр, в кантоне Домпьер-сюр-Бебр в департаменте Алье, в исторической области Овернь, в регионе Овернь — Рона — Альпы. Построен в XII веке. Признан историческим памятником Франции, По своему типу относится к замкам на вершине.","w":"https://ru.wikipedia.org/wiki/%D0%A2%D1%83%D1%80%D0%B8_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2242401":{"n":"Замок Меэн-сюр-Йевр"},"ch-Q8592":{"n":"Замок Пьер-Сиз","c":"Бывший замок в Лионе, Франция","r":"За́мок Пьер-Сиз — исторический замок в Лионе, располагавшийся на берегу Соны в нынешнем 9 округе города, в районе набережной Пьер-Сиз. Разрушен в 1793 году, во время Великой французской революции.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%9F%D1%8C%D0%B5%D1%80-%D0%A1%D0%B8%D0%B7"},"ch-Q388174":{"n":"Шато Пальмер","r":"Шато́ Пальмер́ — французское винодельческое хозяйство, расположенное в департаменте Жиронда, в местечке Марго. Виноградники находится в Медоке, на левом берегу Гаронны и относятся к аппелласьену Марго субрегиона О-Медок (Бордо).","w":"https://ru.wikipedia.org/wiki/%D0%A8%D0%B0%D1%82%D0%BE_%D0%9F%D0%B0%D0%BB%D1%8C%D0%BC%D0%B5%D1%80"},"ch-Q388478":{"n":"Шато Кос Д’Эстурнель","r":"Шато Кос Д’Эстурнель — поместье, расположенное в аппелласьене Сэнт Эстеф, субрегиона Медок региона Бордо. На его винодельне производится одноименное красное сухое вино Cos d’Estournel, которое является одним из пятнадцати вин «второго класса» согласно официальной классификации вин Бордо 1855 года.","w":"https://ru.wikipedia.org/wiki/%D0%A8%D0%B0%D1%82%D0%BE_%D0%9A%D0%BE%D1%81_%D0%94%E2%80%99%D0%AD%D1%81%D1%82%D1%83%D1%80%D0%BD%D0%B5%D0%BB%D1%8C"},"ch-Q428854":{"n":"Ла Рош-Курбон","r":"Ла-Рош Курбон — большой замок (шато) в департаменте Приморская Шаранта, во Франции. Расположен в болотистой местности, в коммуне Сен-Поршер между Сентом и Рошфором.","w":"https://ru.wikipedia.org/wiki/%D0%9B%D0%B0_%D0%A0%D0%BE%D1%88-%D0%9A%D1%83%D1%80%D0%B1%D0%BE%D0%BD"},"ch-Q1014264":{"n":"Турноэль","r":"Замок Турноэль — средневековый замок во Франции в коммуне Вольвик региона Овернь.","w":"https://ru.wikipedia.org/wiki/%D0%A2%D1%83%D1%80%D0%BD%D0%BE%D1%8D%D0%BB%D1%8C"},"ch-Q1014374":{"n":"Вандом (замок)","r":"Замок Вандом был основан в X веке как крепость, а в XIV–XVI веках превратился в роскошную резиденцию герцогов Вандомских – боковой ветви королевской династии Бурбонов.","w":"https://ru.wikipedia.org/wiki/%D0%92%D0%B0%D0%BD%D0%B4%D0%BE%D0%BC_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q939256":{"n":"Шато Ласкомб"},"ch-Q1011058":{"n":"Замок Бланди-ле-Тур","c":"замок"},"ch-Q1661220":{"n":"Шато-де-Валь","c":"Средневековый замок во Франции","r":"Шато-де-Валь — средневековый замок, основанный в XIII веке. Комплекс несколько раз перестраивался и реставрировался. Находится в коммуне Ланобр в департаменте Канталь, в регионе Овернь — Рона — Альпы, Франция. В сентябре 1946 года замок признан историческим памятником. Хотя крепость расположена на территории коммуны Ланобр, после строительства плотины она стала собственностью коммуны Бор-лез-Орг, которая находится в департаменте Коррез.","w":"https://ru.wikipedia.org/wiki/%D0%92%D0%B0%D0%BB%D1%8C_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1666762":{"n":"Замок Ланке","r":"Замок Ланке — французский замок, находящийся на территории коммуны Ланке в департаменте Дордонь. Строительство замка велось в XV—XVI веках. В 1942 году шато классифицировано как национальный исторический памятник. Посещение возможно.","w":"https://ru.wikipedia.org/wiki/%D0%9B%D0%B0%D0%BD%D0%BA%D0%B5_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2242017":{"n":"Шато-де-Ла-Рошпо","r":"Шато-де-Ла-Рошпо — это феодальный замок XII века в неоготическом бургундском стиле, который был перестроен в XV веке, а в XIX веке полностью восстановлен, покрыт глазурованной бургундской черепицей и находится в Ла-Рошпо, департамент Кот-д'Ор, регион Бургундия — Франш-Конте.","w":"https://ru.wikipedia.org/wiki/%D0%9B%D0%B0-%D0%A0%D0%BE%D1%88%D0%BF%D0%BE_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1720411":{"n":"шато Ротшильд","c":"руины замка во Франции"},"ch-Q2240680":{"n":"Замок Дюнуа","r":"За́мок Дюнуа́ — средневековый замок в городе Божанси департамента Луаре, в центральной Франции. В 1925 году замок внесён в список исторических памятников Франции.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%94%D1%8E%D0%BD%D1%83%D0%B0"},"ch-Q2971702":{"n":"Гран-Жарден (замок)","r":"Гран-Жарден — усадьба первого герцога Гиза, построенная в 1533—1546 годах в стиле Возрождения в лотарингском городе Жуанвиль. Главный, или банкетный дом представлял собой крупный павильон, предназначенный для вечеринок и развлечений.","w":"https://ru.wikipedia.org/wiki/%D0%93%D1%80%D0%B0%D0%BD-%D0%96%D0%B0%D1%80%D0%B4%D0%B5%D0%BD"},"ch-Q3292683":{"n":"Дворец Камбон","r":"Дворец Камбон — дворец, расположенный в 1-м округе Париже на одноимённой улице Камбон. В нём размещается Счётная палата Франции, а также Суд бюджетной и фискальной дисциплины.","w":"https://ru.wikipedia.org/wiki/%D0%94%D0%B2%D0%BE%D1%80%D0%B5%D1%86_%D0%9A%D0%B0%D0%BC%D0%B1%D0%BE%D0%BD"},"ch-Q2969586":{"n":"Замок Ла-Рош","c":"французский замок в коммуне Сен-Прист-ла-Рош","r":"Ла-Рош — средневековый замок в излучине реки Луара в коммуне Сен-Прэ-ла-Рош, в регионе Овернь — Рона — Альпы, в 20 км к югу от Роана, Франция.","w":"https://ru.wikipedia.org/wiki/%D0%9B%D0%B0-%D0%A0%D0%BE%D1%88_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA%2C_%D0%A1%D0%B5%D0%BD-%D0%9F%D1%80%D0%B8%D1%81%D1%82-%D0%BB%D0%B0-%D0%A0%D0%BE%D1%88)"},"ch-Q2969647":{"n":"Ландревиль (замок)","r":"Замок Ландревиль — замок, расположенный в коммуне Байонвиль в департаменте Арденны Франции.","w":"https://ru.wikipedia.org/wiki/%D0%9B%D0%B0%D0%BD%D0%B4%D1%80%D0%B5%D0%B2%D0%B8%D0%BB%D1%8C_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2628194":{"n":"Олан","c":"Средневековый замок во Франции","r":"Олен — средневековый замок во Франции. Расположен в коммуне Френикур-ле-Дольман, в округе Бетюн, в департаменте Па-де-Кале, в регионе О-де-Франс, Франция. Является одним из лучших образцов средневековой фортификации в бывшем регионе Нор — Па-де-Кале. По своему типу относится к замкам на воде.","w":"https://ru.wikipedia.org/wiki/%D0%9E%D0%BB%D0%B5%D0%BD_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2970343":{"n":"Шато-де-Радан"},"ch-Q2968803":{"n":"Казнёв","r":"Замок Казнёв — укреплённый замок в Новой Аквитании, находящийся близ коммуны Прешак, департамент Жиронда (Франция). Расположен посреди обширного парка, на берегу реки Сирон. Имение находится в частной собственности, им владеет герцогский род Сабран-Понтевес. 24 сентября 1965 года замок и парк получили статус исторического памятника Франции.","w":"https://ru.wikipedia.org/wiki/%D0%9A%D0%B0%D0%B7%D0%BD%D1%91%D0%B2_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2968153":{"n":"Замок д'Обири","c":"Необарочный замок XIX века на юге Франции","r":"Д’Обири́ — эклектичный замок в стиле необарокко, построенный в конце XIX века недалеко от города Сере, в департаменте Восточные Пиренеи, в регионе Окситания, Франция.","w":"https://ru.wikipedia.org/wiki/%D0%94%E2%80%99%D0%9E%D0%B1%D0%B8%D1%80%D0%B8_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2243297":{"n":"Замок Сен-Жермен-де-Ливе","c":"Ренессансный замковый комплекс во Франции","r":"Сен-Жермен-де-Ливе — старинная замковая резиденция во Франции. Находится в исторической области Пэи д'Ож, в коммуне Сен-Жермен-де-Ливе, в департаменте Кальвадос, в регионе Нормандия. Дошедший до нашего времени комплекс возведён в XV-XVI веке. Комплекс в 1924 году был признан историческим памятником. По своему типу относится к замкам на воде.","w":"https://ru.wikipedia.org/wiki/%D0%A1%D0%B5%D0%BD-%D0%96%D0%B5%D1%80%D0%BC%D0%B5%D0%BD-%D0%B4%D0%B5-%D0%9B%D0%B8%D0%B2%D0%B5_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2969972":{"n":"Замок Монбельяр","r":"Замок Монбельяр — резиденция правителей княжества Монбельяр.","w":"https://ru.wikipedia.org/wiki/%D0%9C%D0%BE%D0%BD%D0%B1%D0%B5%D0%BB%D1%8C%D1%8F%D1%80_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q3078351":{"n":"Геклен (остров)","r":"Гекле́н — остров у побережья Бретани в проливе Ла-Манш, входит в состав департамента Иль и Вилен, Франция. Остров находится недалеко от побережного городка Санкт-Кулон и во время отливов становится доступен по суше. Долгое время остров являлся важным опорным стратегическим пунктом в защите Бретани, на данный момент о военном прошлом острова напоминают лишь руины форта Геклен.","w":"https://ru.wikipedia.org/wiki/%D0%93%D0%B5%D0%BA%D0%BB%D0%B5%D0%BD_(%D0%BE%D1%81%D1%82%D1%80%D0%BE%D0%B2)"},"ch-Q2693243":{"n":"Замок Бретеш","c":"Дворцово-замковый комплекс во Франции","r":"Бретеш — дворцово-замковый комплекс в коммуне Мисийяк, департамент Атлантическая Луара региона Пеи-де-ла-Луар, Франция. Первый замок на этом месте был построен в XIV веке. Существующее ныне здание возведено в XIX веке в ходе масштабной реконструкции. По своему типу относится к замкам на воде.","w":"https://ru.wikipedia.org/wiki/%D0%91%D1%80%D0%B5%D1%82%D0%B5%D1%88_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2971917":{"n":"Брюникель","c":"замок","r":"Брюникель — замок в французской коммуне Брюникель, в департаменте Тарн и Гаронна.","w":"https://ru.wikipedia.org/wiki/%D0%91%D1%80%D1%8E%D0%BD%D0%B8%D0%BA%D0%B5%D0%BB%D1%8C_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2374744":{"n":"Замок Берзе","c":"Крупный замковый комплекс во Франции","r":"Берзе — средневековый замковый комплекс во Франции. Расположен в коммуне Берзе-ле-Шатель в департаменте Сона и Луара, в южной части исторического региона Бургундия, ныне — регион Бургундия — Франш-Конте. В 1983 году признан памятником архитектуры Франции. Один из 14 объектов на популярном маршруте «Замки Южной Бургундии». Находится в частной собственности. Министерством культуры признан историческим памятником. По своему типу относится к замкам на вершине.","w":"https://ru.wikipedia.org/wiki/%D0%91%D0%B5%D1%80%D0%B7%D0%B5_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2255651":{"n":"Замок Монтротье","c":"Средневековый каменный замок во Франции","r":"Монтротье — средневековый каменный замок, возведённый в XIII веке. Расположен в коммуне Лованьи, в департаменте Верхняя Савойя, в историческом регионе Овернь — Рона — Альпы, Франция. Замок находится в десяти километрах к западу от города Анси, недалеко от природного парка «ущелий Фьер», Признан властями Франции охраняемым памятником архитектуры. По своему типу относится к замкам на вершине.","w":"https://ru.wikipedia.org/wiki/%D0%9C%D0%BE%D0%BD%D1%82%D1%80%D0%BE%D1%82%D1%8C%D0%B5_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2081177":{"n":"Дворец герцогов Лотарингских"},"ch-Q15940508":{"n":"Замок Вирьё","c":"Средневековый замковый комплекс во Франции","r":"Вирьё — средневековый каменный замок во Франции. Расположен в коммуне Валь-де-Вирьё, в департаменте Изер, в историческом регионе Овернь — Рона — Альпы. Возведён в XI веке. На протяжении своего существования многократно перестраивался. Признан властями Франции охраняемым памятником архитектуры. По своему типу относится к замкам на вершине.","w":"https://ru.wikipedia.org/wiki/%D0%92%D0%B8%D1%80%D1%8C%D1%91_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA%2C_%D0%98%D0%B7%D0%B5%D1%80)"},"ch-Q773649":{"n":"Замок Монбазияк","r":"Монбазийак — замок на юго-западе Франции, в департаменте Дордонь в нескольких километрах от Бержерака.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%9C%D0%BE%D0%BD%D0%B1%D0%B0%D0%B7%D0%B8%D0%B9%D0%B0%D0%BA"},"ch-Q577444":{"n":"Шамплатрё","c":"замок во Франции"},"ch-Q1090622":{"n":"Шато Понте-Кане","r":"Шато Понте-Кане — винодельческое хозяйство в апелласьоне Медок, в области Бордо. Château Pontet-Canet является также названием красного вина, производимого этим хозяйством. Вино, произведенное здесь, входит в состав одного из восемнадцати пятых крю в Официальной классификации вин Бордо 1855 года.","w":"https://ru.wikipedia.org/wiki/%D0%A8%D0%B0%D1%82%D0%BE_%D0%9F%D0%BE%D0%BD%D1%82%D0%B5-%D0%9A%D0%B0%D0%BD%D0%B5"},"ch-Q1493082":{"n":"Озер (замок)","c":"замок во Франции","r":"Озер — средневековый замок, серьёзно перестроенный в XVI веке. Расположен в коммуне Озер, в департаменте Канталь, в историческом регионе Овернь — Рона — Альпы, Франция. Признан охраняемым памятником архитектуры.","w":"https://ru.wikipedia.org/wiki/%D0%9E%D0%B7%D0%B5%D1%80_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1519303":{"n":"замок Нидек","c":"замок в Эльзасе, Франция"},"ch-Q1821831":{"n":"Пестейль","c":"Средневековый замковый комплекс во Франции","r":"Пестейль, также иногда упоминается как Польминьяк , — средневековый замок во Франции. Расположен в коммуне Польминьяк, в кантоне Вик-сюр-Сер, департаменте Канталь, в историческом регионе Овернь — Рона — Альпы. Возведён в XIV веке. В последующие столетия неоднократно перестраивался. Комплекс внесён в список исторических памятников Франции 18 июля 1994 года. По своему типу относится к замкам на вершине.","w":"https://ru.wikipedia.org/wiki/%D0%9F%D0%B5%D1%81%D1%82%D0%B5%D0%B9%D0%BB%D1%8C_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2240085":{"n":"Замок Аржи","c":"Средневековый замок в Долине Луары, Франция","r":"Аржи — средневековый замок в доренессансном стиле, в целом соответствовал традициям архитектуры эпохи Людовика XII. Замок расположен в самом сердце бывшего герцогства Берри, на территории коммуны Аржи, в департаменте Эндр, в центральной части региона Долина Луары, Франция.","w":"https://ru.wikipedia.org/wiki/%D0%90%D1%80%D0%B6%D0%B8_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2240171":{"n":"Замок Банн","c":"Средневековый замок во Франции","r":"Банн — замок в коммуне Бомон-дю-Перигор департамента Дордонь, во французском регионе Аквитания. По своему типу относится к замкам на вершине. В нынешнем виде построен Биронами в начале XVI века, а затем капитально отреставрирован в конце XIX века. Частное владение, закрытое для посещения туристами.","w":"https://ru.wikipedia.org/wiki/%D0%91%D0%B0%D0%BD%D0%BD_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2240557":{"n":"Коньяк (замок)","r":"Замок Коньяк — средневековый замок в одноимённом городе. Также известен как замок Валуа или замок Франциска I.","w":"https://ru.wikipedia.org/wiki/%D0%9A%D0%BE%D0%BD%D1%8C%D1%8F%D0%BA_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2968560":{"n":"замок Бизи","c":"замок в Верноне, Франция","r":"Усадьба Бизи — дворцово-парковый комплекс (шато) во французской коммуне Вернон, в департаменте Эр административного региона Верхняя Нормандия. Входит в список французских королевских резиденций.","w":"https://ru.wikipedia.org/wiki/%D0%91%D0%B8%D0%B7%D0%B8"},"ch-Q2968633":{"n":"Бурсо (замок)","r":"Замок Бурсо — неоренессансный замок в Бурсо, департамент Марна, северо-восточная Франция. Он был построен между 1843 и 1850 годами мадам Клико Понсарден, вдовой Клико, которая владела домом шампанского Вдова Клико. Он был продан её наследником семье Берри из Канады с 1913 по 1927 год и использовался в качестве военного госпиталя во время Первой и Второй мировых войн. Сегодня шампанское марки Château de Boursault производится из винограда, выращенного на виноградниках вокруг замка, и выдерживается в его погребах.","w":"https://ru.wikipedia.org/wiki/%D0%91%D1%83%D1%80%D1%81%D0%BE_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2970979":{"n":"Виньи (замок)","r":"Виньи — Ренессансный замковый комплекс во Франции. Расположен в коммуне Виньи, в департаменте Валь-д’Уаз, в северной части исторического региона Иль-де-Франс. В 1983 году признан памятником архитектуры Франции. Строительство началось в 1504 году. В 1867 года сооружение было перестроено в стиле трубадуров. Находится в частной собственности. В 1984 году Министерством культуры признан историческим памятником. По своему типу относится к замкам на воде.","w":"https://ru.wikipedia.org/wiki/%D0%92%D0%B8%D0%BD%D1%8C%D0%B8_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2243666":{"n":"Замок Сюлли","c":"Старинный замок во Франции","r":"Сюлли — старинный замковый комплекс во Франции. Расположен в коммуне Сюлли в департаменте Сона и Луара, в южной части исторического региона Бургундия, ныне — регион Бургундия — Франш-Конте, Франция. Замок расположен между городами Бон и Отён. Признан памятником архитектуры Франции. Замок является частной собственностью: с середины XVIII века он служит родовой резиденцией семье Мак Магон, герцогам де Маджента. При этом комплекс открыт для посещения. Это один из 14 объектов, доступных для публики, которые объединены в проект «Маршруты замков Южной Бургундии». По своему типу относится к замкам на воде.","w":"https://ru.wikipedia.org/wiki/%D0%A1%D1%8E%D0%BB%D0%BB%D0%B8_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2968138":{"n":"Замок д’Аньер"},"ch-Q2967867":{"n":"Шато Деганн","r":"Дворец Деган(н)а — общественное здание во французском курорте Аркашон. В его стенах располагается городское казино Аркашона, также известное как «пляжное казино».","w":"https://ru.wikipedia.org/wiki/%D0%A8%D0%B0%D1%82%D0%BE_%D0%94%D0%B5%D0%B3%D0%B0%D0%BD%D0%BD"},"ch-Q2970222":{"n":"Замок Пьеррекло","c":"Дворцово-замковый комплекс во Франции","r":"Пьеррекло — замковый комплекс в коммуне Пьеррекло в департаменте Сона и Луара, в южной части исторического региона Бургундия, ныне — регион Бургундия — Франш-Конте, Франция. Замок расположен примерно в 15 км к западу от города Макон. По своему типу относится к замкам на вершине. В 1984 году признан памятником архитектуры Франции. Замок является частной собственностью.","w":"https://ru.wikipedia.org/wiki/%D0%9F%D1%8C%D0%B5%D1%80%D1%80%D0%B5%D0%BA%D0%BB%D0%BE_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2969963":{"n":"Замок Монброн (Шаранта)","r":"Замок Монброн, который местные жители называют Старым замком, расположен в Монброне, в департаменте Шаранта, во Франции.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%9C%D0%BE%D0%BD%D0%B1%D1%80%D0%BE%D0%BD_(%D0%A8%D0%B0%D1%80%D0%B0%D0%BD%D1%82%D0%B0)"},"ch-Q3078149":{"n":"Фор-де-Буа-л'Аббе","r":"Фор-де-Буа-л’Аббе — крепость, построенная между 1883 и 1885 гг. Является частью укреплений города Эпиналь. Представяет собой пример системы укреплений Сере-де-Ривьер. Форт избежал значительных изменений в годы, предшествующие Первой мировой войне, и функционирует в настоящее время как музей.","w":"https://ru.wikipedia.org/wiki/%D0%91%D1%83%D0%B0-%D0%BB%E2%80%99%D0%90%D0%B1%D0%B1%D0%B5_(%D0%BA%D1%80%D0%B5%D0%BF%D0%BE%D1%81%D1%82%D1%8C)"},"ch-Q2715327":{"n":"Замок Кастийон","r":"Замок Кастийон — средневековый замок, расположенный во французской коммуне Арангос в департаменте Ланды региона Аквитания. Его фасады и кровля, исключая современный флигель, сооружённый справа от главного здания, 9 декабря 1948 года внесены в дополнительный список национальных исторических памятников.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%9A%D0%B0%D1%81%D1%82%D0%B8%D0%B9%D0%BE%D0%BD"},"ch-Q2969692":{"n":"Замок Лавут-Полиньяк","r":"Замок Лавут-Полиньяк — средневековый замок, расположенный в городе Лавуте-сюр-Луар, в департаменте Верхняя Луара, в регионе Овернь-Рона-Альпы, Франция.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%9B%D0%B0%D0%B2%D1%83%D1%82-%D0%9F%D0%BE%D0%BB%D0%B8%D0%BD%D1%8C%D1%8F%D0%BA"},"ch-Q2968317":{"n":"Замок Орион","r":"Замок Орьон — замок XVII века, расположенный на Юге Франции около деревни Орьон департамент Атлантические Пиренеи. В замке сохранились мебель и предметы искусства, портреты предыдущих хозяев замка, их письма, книги, одежду разных эпох и предметы личного пользования.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%9E%D1%80%D1%8C%D0%BE%D0%BD"},"ch-Q15943705":{"n":"Замок Сайан","c":"Средневековый замок во Франции","r":"Сайан — средневековый замок, расположенный в коммуне Андла в департаменте Канталь, примерно в десяти километрах от города Сен-Флур, в регионе Овернь — Рона — Альпы, Франция. По своему типу относится к замкам на вершине. Комплекс внесён в список исторических памятников в сентября 2019 года. Рядом расположен водопад Сайан.","w":"https://ru.wikipedia.org/wiki/%D0%A1%D0%B0%D0%B9%D0%B0%D0%BD_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q22949563":{"n":"Замок Бон","c":"Замок XIX века во Франции","r":"Бон — замок, построенный в XIX веке. Расположен в коммуне Линьи-ле-Рибо, в департаменте Луаре, в регионе Центр — Долина Луары, Франция.","w":"https://ru.wikipedia.org/wiki/%D0%91%D0%BE%D0%BD_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q19152931":{"n":"Замок Корно","c":"Неоготический замок во Франции в департаменте Юра","r":"Корно — замок в неоготическом стиле в коммуне Корно в департаменте Юра в регионе Франш-Конте, Франция. Современное здание построено на месте средневекового замка в 1876 году. В настоящее время является частным владением.","w":"https://ru.wikipedia.org/wiki/%D0%9A%D0%BE%D1%80%D0%BD%D0%BE_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q1090324":{"n":"Шато Батайи","c":"винодельческое хозяйство"},"ch-Q952229":{"n":"Эрменонвиль","c":"усадьба в селе Эрменонвиль, в департаменте Уаза на севере Франции, в 40 километрах к северу от Парижа","r":"Шато д’Эрменонвиль — усадьба в селе Эрменонвиль, в департаменте Уаза на севере Франции, в 40 километрах к северу от Парижа. В 1778 году здесь умер и был захоронен Жан-Жак Руссо. В 1980-е годы Эрменонвиль служил штаб-квартирой Международного общества сознания Кришны (ИСККОН) во Франции. В этот период кришнаиты дали усадьбе новое название — Кришнавиль.","w":"https://ru.wikipedia.org/wiki/%D0%AD%D1%80%D0%BC%D0%B5%D0%BD%D0%BE%D0%BD%D0%B2%D0%B8%D0%BB%D1%8C_(%D1%83%D1%81%D0%B0%D0%B4%D1%8C%D0%B1%D0%B0)"},"ch-Q964638":{"n":"замок Рипай"},"ch-Q1847415":{"n":"замок Берни"},"ch-Q2969604":{"n":"Замок Лабри","r":"Замок Лабри или замок д'Альбре — средневековый замок, остатки которого находятся во французской коммуне Лабри в департаменте Ланды. Сооружённый из дерева и грунта в 1225—1230 годах, замок являлся колыбелью благородного гасконского рода сеньоров Альбре, который, начавшись здесь, наращивал своё влияние с течением столетий, вплоть до восхождения на французский престол одного из своих представителей, короля Генриха IV.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%9B%D0%B0%D0%B1%D1%80%D0%B8"},"ch-Q2968726":{"n":"замок Бенувиль","c":"замок во Франции"},"ch-Q2970472":{"n":"Ревейон (усадьба)","r":"Усадьба Ревейон — шато XVII века в коммуне Ревейон в департаменте Марна на северо-востоке Франции, в 82 километрах к востоку от Парижа.","w":"https://ru.wikipedia.org/wiki/%D0%A0%D0%B5%D0%B2%D0%B5%D0%B9%D0%BE%D0%BD_(%D1%83%D1%81%D0%B0%D0%B4%D1%8C%D0%B1%D0%B0)"},"ch-Q2751516":{"n":"замок Монтью"},"ch-Q2969166":{"n":"Дюрас","r":"Замок Дюрас — средневековый замок в Новой Аквитании, в коммуне Дюрас. Замок включён в перечень исторических памятников Франции; находится в собственности коммуны.","w":"https://ru.wikipedia.org/wiki/%D0%94%D1%8E%D1%80%D0%B0%D1%81_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA%2C_%D0%A4%D1%80%D0%B0%D0%BD%D1%86%D0%B8%D1%8F)"},"ch-Q2970349":{"n":"Замок Равиньян","r":"Равиньян — дворянская усадьба (шато) во французской коммуне Перки в департаменте Ланды региона Новая Аквитания. Существующий облик приобрёл в XVII веке.","w":"https://ru.wikipedia.org/wiki/%D0%A0%D0%B0%D0%B2%D0%B8%D0%BD%D1%8C%D1%8F%D0%BD_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2971630":{"n":"Замок Буске","c":"Средневековый замок в департаменте Аверон","r":"Буске — средневековый каменный замок, расположенный в коммуне Монперу в департаменте Аверон, в регионе Окситания, Франция. По своему типу относится к замкам на вершине. Комплекс отреставрирован и входит в список исторических памятников Франции.","w":"https://ru.wikipedia.org/wiki/%D0%91%D1%83%D1%81%D0%BA%D0%B5_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA%2C_%D0%90%D0%B2%D0%B5%D1%80%D0%BE%D0%BD)"},"ch-Q2968823":{"n":"Chateau de Challain"},"ch-Q2968909":{"n":"Замок Шазле","c":"Средневековый замок во Франции","r":"Шазле — средневековый замок, серьёзно перестроенный в XVI веке. Расположен в коммуне Шазле, в департаменте Эндр, в округе Ле-Блан, в историческом регионе Центр — Долина Луары, Франция. Признан охраняемым памятником архитектуры. По своему типу относится к замкам на воде.","w":"https://ru.wikipedia.org/wiki/%D0%A8%D0%B0%D0%B7%D0%BB%D0%B5_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2971874":{"n":"Château La Mission Haut-Brion","r":"Шато Ля Миссион О-Брион — винодельческое хозяйство, расположенное в коммуне Таланс, относится к аппелласьону Пессак-Леоньян субрегиона Грав винодельческого региона Бордо. Производит сухие красные и белые вина. В 1953 году красное вино было включено в классификацию Грава.","w":"https://ru.wikipedia.org/wiki/%D0%A8%D0%B0%D1%82%D0%BE_%D0%9B%D1%8F_%D0%9C%D0%B8%D1%81%D1%81%D0%B8%D0%BE%D0%BD_%D0%9E-%D0%91%D1%80%D0%B8%D0%BE%D0%BD"},"ch-Q2969704":{"n":"Левевилль (замок)","r":"Замок Левевиль находится в предместье города Шартр Байо Левек, департамент Эр и Луар. Построен в XV—XVII веках, относится к избранному числу замков Луары.","w":"https://ru.wikipedia.org/wiki/%D0%9B%D0%B5%D0%B2%D0%B5%D0%B2%D0%B8%D0%BB%D1%8C"},"ch-Q2276937":{"n":"Монтегю","r":"Замок Монтегю́ — замок XVIII века у Ланёввиль-деван-Нанси рядом с Нанси. Принадлежит Лотарингскому музею.","w":"https://ru.wikipedia.org/wiki/%D0%9C%D0%BE%D0%BD%D1%82%D0%B5%D0%B3%D1%8E_(%D1%83%D1%81%D0%B0%D0%B4%D1%8C%D0%B1%D0%B0_%D0%B2_%D0%9B%D0%BE%D1%82%D0%B0%D1%80%D0%B8%D0%BD%D0%B3%D0%B8%D0%B8)"},"ch-Q2383887":{"n":"Меридон","c":"Дворцово-замковый комплекс во Франции","r":"Меридон — старинный замок, расположенный в коммуне Шеврёз, в департаменте Ивелин, в историческом регионе Иль-де-Франс, Франция.","w":"https://ru.wikipedia.org/wiki/%D0%9C%D0%B5%D1%80%D0%B8%D0%B4%D0%BE%D0%BD_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2970772":{"n":"Замок Тер-Нёв","c":"Замок стиля Ренесанс  1580г","r":"Замок Тер-Нёв находится в коммуне Фонтене-ле-Конт, в департаменте Вандея, на западе Франции. Замок построен в стиле Ренессанс в 1580 году Жаном Мориссоном, городским архитектором, для Николя Рапана, магистрата, поэта и солдата, Главого Прево коннетабля Франции, и к тому же, компаньона короля Генриха IV Наваррского.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%A2%D0%B5%D1%80-%D0%9D%D1%91%D0%B2"},"ch-Q2062506":{"n":"Замок Бресс-сюр-Грон","c":"Старинный замок во Франции в регионе Бургундия — Франш-Конте","r":"Бресс-сюр-Грон — средневековый замок, расположенный в городке Бресс-сюр-Грон, в департаменте Сона и Луара, в регионе Бургундия — Франш-Конте, Франция. 21 марта 1983 комплекс внесён в список исторических памятников Франции.","w":"https://ru.wikipedia.org/wiki/%D0%91%D1%80%D0%B5%D1%81%D1%81-%D1%81%D1%8E%D1%80-%D0%93%D1%80%D0%BE%D0%BD_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q28040794":{"n":"Замок Помпадур","c":"Старинный замок во Франции","r":"Помпадур — средневековый каменный замок во Франции. Расположен в коммуне Арнак-Помпадур, в кантоне Люберсак, в департаменте Коррез, в регионе Новая Аквитания. Построен в XI веке. В 1926 году внесён в список исторических памятников Франции. По своему типу относится к замкам на воде.","w":"https://ru.wikipedia.org/wiki/%D0%9F%D0%BE%D0%BC%D0%BF%D0%B0%D0%B4%D1%83%D1%80_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2970085":{"n":"Шато де Мюра"},"ch-Q2970092":{"n":"Мелак","c":"французский замок","r":"За́мок Мела́к — за́мок XIV—XVI веков на юге Франции в исторической провинции Руэрг, современный департамент Аверон. Памятник истории.","w":"https://ru.wikipedia.org/wiki/%D0%9C%D0%B5%D0%BB%D0%B0%D0%BA_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2968596":{"n":"замок Бонвиль"},"ch-Q2968762":{"n":"Шато де Канон","c":"достопримечательность в коммуне Мезидон-Валле-д’Ож, Нормандия"},"ch-Q2970896":{"n":"Вальми","c":"замок в стиле модерн","r":"Вальми — замок в стиле модерн, типичный для Прекрасной эпохи, построенный на холме в коммуне Аржеле-сюр-Ме в департаменте Восточные Пиренеи, регион Окситания, Франция.","w":"https://ru.wikipedia.org/wiki/%D0%92%D0%B0%D0%BB%D1%8C%D0%BC%D0%B8_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2970938":{"n":"Замок Вандёвр-сюр-Барс","r":"Замок Вандёвр-сюр-Барс — средневековый замок Франции, расположенный в коммуне Вандёвр-сюр-Барс департамента Об региона Гранд-Эст. Известен с 1107 года.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%92%D0%B0%D0%BD%D0%B4%D1%91%D0%B2%D1%80-%D1%81%D1%8E%D1%80-%D0%91%D0%B0%D1%80%D1%81"},"ch-Q2970982":{"n":"Шато де Вильжени"},"ch-Q2970415":{"n":"Ромефор (замок, Эндр)","r":"Ромефор — средневековый замковый комплекс в коммуне Сирон в департаменте Эндр, в регионе Центр — Долина Луары, Франция. Крепость возведена в XII веке и на том этапе являлась самым крупным каменным фортификационным сооружением подобного рода. Ромефор не раз перестраивался и реконструировался. В 1993 году основная часть комплекса была признана во Франции историческим памятником архитектуры. По своему типу относиться к замкам на вершине.","w":"https://ru.wikipedia.org/wiki/%D0%A0%D0%BE%D0%BC%D0%B5%D1%84%D0%BE%D1%80_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA%2C_%D0%AD%D0%BD%D0%B4%D1%80)"},"ch-Q2633925":{"n":"замок Ольнуа","c":"замок в Ольнуа-сюр-Сей, Франция"},"ch-Q2970398":{"n":"Рошфор-ан-Ивелин","c":"Руины средневекового замка в департаменте Ивелин, регион Иль-де-Франс, Франция","r":"Замок Рошфо́р-ан-Ивели́н — руины средневекового замка в департаменте Ивелин, регион Иль-де-Франс, Франция. Расположен на территории одноимённой коммуны Рошфор-ан-Ивелин. С 7 октября 1931 года частично имеет статус исторического памятника — в список были включены башня замка и здание XIX века в стиле эпохи Людовика XIII.","w":"https://ru.wikipedia.org/wiki/%D0%A0%D0%BE%D1%88%D1%84%D0%BE%D1%80-%D0%B0%D0%BD-%D0%98%D0%B2%D0%B5%D0%BB%D0%B8%D0%BD_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2970608":{"n":"Замок Салиньи","c":"Замковый комплекс во Франции","r":"Салиньи — средневековый замок во Франции. Расположен в коммуне Салиньи-сюр-Рудон, в кантоне Домпьер-сюр-Бебр, в округе Мулен, департаменте Алье, в историческом регионе Овернь — Рона — Альпы. Возведён в XIII веке в долине реки Рудон. В последующие столетия неоднократно перестраивался. Комплекс внесён в список исторических памятников Франции в 2008 году. По своему типу относится к замкам на воде.","w":"https://ru.wikipedia.org/wiki/%D0%A1%D0%B0%D0%BB%D0%B8%D0%BD%D1%8C%D0%B8_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2942728":{"n":"замок де ля Флашер"},"ch-Q2968809":{"n":"Замок Шабене","c":"Дворцово-замковый комплекс в центральной части Франции","r":"Шабене — средневековый замок расположенный к северу от одноимённой деревни в коммуне Ле-Пон-Кретьен-Шабене, в департаменте Эндр, в регионе Центр — Долина Луары, Франция. Признан историческим памятником. В настоящее время замок является респектабельным отелем.","w":"https://ru.wikipedia.org/wiki/%D0%A8%D0%B0%D0%B1%D0%B5%D0%BD%D0%B5_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2969277":{"n":"Фретеваль (замок)","r":"Замок Фретеваль - замок, построенный в первой половине XI веке, остатки которого находятся во французской коммуне Фретеваль в департаменте Луар и Шер, в регионе Центр-Валь-де-Луара. Он был построен в XI веке как крепость, контролирующая долину реки Луары. В XII веке он перешел к графам Блуа.","w":"https://ru.wikipedia.org/wiki/%D0%A4%D1%80%D0%B5%D1%82%D0%B5%D0%B2%D0%B0%D0%BB%D1%8C_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2968963":{"n":"Шатовьё (замок, Верхняя Савойя)","r":"Шатовьё – средневековый замок на юго-востоке Франции. Также иногда встречается название «Замок Дюэн». Расположен на скалистом острове на берегу озера Анси в коммуне Дюэн, к востоку от городка Сен-Жорьо, в департаменте Верхняя Савойя, в регионе Овернь — Рона — Альпы. За время своего существования многократно перестраивался. Включён в список Памятников архитектуры Франции. Благодаря живописному расположению служил излюбленным объектом многих художников. По своему типу комплекс относится к замкам на воде.","w":"https://ru.wikipedia.org/wiki/%D0%A8%D0%B0%D1%82%D0%BE%D0%B2%D1%8C%D1%91_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA%2C_%D0%92%D0%B5%D1%80%D1%85%D0%BD%D1%8F%D1%8F_%D0%A1%D0%B0%D0%B2%D0%BE%D0%B9%D1%8F)"},"ch-Q2405910":{"n":"замок Мондардье"},"ch-Q2971220":{"n":"замок де ля Фаворит","c":"замок в Люневиле, Франция"},"ch-Q2968254":{"n":"Замок Эльфеданж","r":"Замок Эльфеданж — фортификационное сооружение XII века. Замок расположен в окрестностях Генгланжа.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%AD%D0%BB%D1%8C%D1%84%D0%B5%D0%B4%D0%B0%D0%BD%D0%B6"},"ch-Q2968386":{"n":"Замок Эпуас","c":"Дворцово-замковый комплекс во Франции","r":"Эпуас — средневековый замковый комплекс во Франции. Расположен в одноимённой коммуне, в кантоне Семюр-ан-Осуа, в департаменте Кот-д’Ор, в северной части исторического региона Бургундия, ныне — регион Бургундия — Франш-Конте. По своему типу относится к замкам на вершине. В 1946 году признан памятником архитектуры Франции. В комплексе до сих пор расположена местная действующая приходская церковь.","w":"https://ru.wikipedia.org/wiki/%D0%AD%D0%BF%D1%83%D0%B0%D1%81_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2969760":{"n":"Замок Люссан","r":"Замок Люсса́н — замок XV—XVII веков, расположенный на юге Франции, в коммуне Люссан,. Замок принадлежит коммуне, в нём расположена мэрия.","w":"https://ru.wikipedia.org/wiki/%D0%9B%D1%8E%D1%81%D1%81%D0%B0%D0%BD_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q2971136":{"n":"Шато де Лабом","c":"замок во Франции"},"ch-Q2090672":{"n":"Замок Bonneville","c":"замок во Франции"},"ch-Q22915915":{"n":"Замок Сент-Уан","c":"замок в Сент-Уан-сюр-Сене, Франция","r":"Дворец Сент-Уан — резиденция, расположенная в Сент-Уан-сюр-Сен, регион Иль-де-Франс, Франция.","w":"https://ru.wikipedia.org/wiki/%D0%94%D0%B2%D0%BE%D1%80%D0%B5%D1%86_%D0%A1%D0%B5%D0%BD%D1%82-%D0%A3%D0%B0%D0%BD"},"ch-Q19607188":{"n":"Замок Оржер","r":"Замок Оржер — замок начала XX века, расположенный в центре города Рив департамент Изер. В 1924—1970 годы принимал иммигрантов из СССР.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%9E%D1%80%D0%B6%D0%B5%D1%80"},"ch-Q21294421":{"n":"Дворец монтобанского епископа"},"ch-Q22248535":{"n":"замок д’Аркур"},"ch-Q22935598":{"n":"Замок Камбон","r":"За́мок Камбо́н — французский замок XV—XVIII веков в деревне Сен-Сернен департамента Канталь.","w":"https://ru.wikipedia.org/wiki/%D0%97%D0%B0%D0%BC%D0%BE%D0%BA_%D0%9A%D0%B0%D0%BC%D0%B1%D0%BE%D0%BD"},"ch-Q22941847":{"n":"Шато де Шавиньи","r":"Шато де Шавиньи — шато в Лерне. Исторический памятник Франции.","w":"https://ru.wikipedia.org/wiki/%D0%A8%D0%B0%D1%82%D0%BE_%D0%B4%D0%B5_%D0%A8%D0%B0%D0%B2%D0%B8%D0%BD%D1%8C%D0%B8"},"ch-Q28494674":{"n":"Брюнуа (замок)","r":"Замок Брюнуа — малый загородный дворец, павильон для отдыха, позднее разрушенный, располагавшийся в коммуне Брюнуа, департамент Эсон, северная Франция. Замок славился великолепными садами во французском регулярном стиле и был любимой резиденцией графа Прованса, будущего Людовика XVIII. В состав имения входили «Большой замок» и «Малый замок», расположенные на другой стороне долины.","w":"https://ru.wikipedia.org/wiki/%D0%91%D1%80%D1%8E%D0%BD%D1%83%D0%B0_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"},"ch-Q78658079":{"n":"Замок Тюрпо","c":"Особняк в виде средневекового замка во Франции","r":"Тюрпо — жилая резиденция в виде старинного замка. Здание расположено в коммуне Киброн, в департаменте Морбиан, в регионе Бретань, Франция.","w":"https://ru.wikipedia.org/wiki/%D0%A2%D1%8E%D1%80%D0%BF%D0%BE_(%D0%B7%D0%B0%D0%BC%D0%BE%D0%BA)"}};
